// userStorageInfo — данные о квоте файлов юзера.
type userStorageInfo struct {
	UsedBytes  int64 `json:"used_bytes"`
	QuotaBytes int64 `json:"quota_bytes"`
	FilesCount int64 `json:"files_count"`
}

// getUserStorage возвращает текущее использование и квоту юзера.
func getUserStorage(db *sql.DB, userID int64) (userStorageInfo, error) {
	var info userStorageInfo
	err := db.QueryRow(`
		SELECT COALESCE(storage_used_bytes, 0), COALESCE(storage_quota_bytes, 1073741824),
		       (SELECT COUNT(*) FROM user_uploads WHERE user_id = $1 AND deleted_at IS NULL)
		FROM users
		WHERE id = $1
	`, userID).Scan(&info.UsedBytes, &info.QuotaBytes, &info.FilesCount)
	return info, err
}

// sitemapBaseURL — базовый URL для sitemap. Берётся из env SITEMAP_BASE_URL,
// иначе из PUBLIC_BASE_URL, иначе строится из request host.
func sitemapBaseURL(r *http.Request) string {
	if u := strings.TrimSpace(os.Getenv("SITEMAP_BASE_URL")); u != "" {
		return strings.TrimRight(u, "/")
	}
	return publicBaseURL(r)
}

// publicBaseURL возвращает базовый URL платформы для генерации ссылок в письмах.
func publicBaseURL(r *http.Request) string {
	if u := strings.TrimSpace(os.Getenv("PUBLIC_BASE_URL")); u != "" {
		return strings.TrimRight(u, "/")
	}
	scheme := "https"
	if r.TLS == nil && r.Header.Get("X-Forwarded-Proto") != "https" {
		scheme = "http"
	}
	return scheme + "://" + r.Host
}

func sendVerificationEmail(ctx context.Context, db *sql.DB, baseURL string, userID int64, toEmail, userName string) error {
	token, err := createEmailVerificationToken(db, userID)
	if err != nil {
		return fmt.Errorf("create verification token: %w", err)
	}
	link := baseURL + "/verify-email.html?token=" + token
	return mail.Send(ctx, toEmail, "Подтвердите ваш email — LASTOP GROUP", buildVerificationEmailHTML(userName, link))
}

func sendPasswordResetEmail(ctx context.Context, db *sql.DB, baseURL string, userID int64, toEmail, userName, ip string) error {
	token, err := createPasswordResetToken(db, userID, ip)
	if err != nil {
		return fmt.Errorf("create reset token: %w", err)
	}
	link := baseURL + "/reset-password.html?token=" + token
	return mail.Send(ctx, toEmail, "Восстановление пароля — LASTOP GROUP", buildPasswordResetEmailHTML(userName, link))
}

