	mux.HandleFunc("/api/repost-targets", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		userID, ok := authenticatedUserID(w, r, sessions)
		if !ok {
			return
		}
		// Personal
		type target struct {
			Type     string `json:"type"` // "user" | "company" | "community"
			ID       int64  `json:"id"`
			PublicID string `json:"public_id,omitempty"`
			Name     string `json:"name"`
			Avatar   string `json:"avatar,omitempty"`
			Subtitle string `json:"subtitle,omitempty"`
		}
		var targets []target
		// 1) Личная страница
		var userName, userAvatar string
		_ = db.QueryRow(`SELECT COALESCE(NULLIF(full_name,''), email), COALESCE(avatar_url, '') FROM users WHERE id=$1`, userID).Scan(&userName, &userAvatar)
		targets = append(targets, target{
			Type:     "user",
			ID:       userID,
			Name:     userName,
			Avatar:   userAvatar,
			Subtitle: "На мою страницу",
		})
		// 2) Компании, где юзер состоит
		rows, err := db.Query(`
			SELECT c.id, c.public_id, c.name, COALESCE(c.logo_image, ''), cm.role
			FROM companies c
			JOIN company_members cm ON cm.company_id = c.id
			WHERE cm.user_id = $1 AND c.deleted_at IS NULL
			ORDER BY c.name
		`, userID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var t target
				var role string
				if err := rows.Scan(&t.ID, &t.PublicID, &t.Name, &t.Avatar, &role); err == nil {
					t.Type = "company"
					if role == "owner" {
						t.Subtitle = "Владелец компании"
					} else {
						t.Subtitle = "Участник компании"
					}
					targets = append(targets, t)
				}
			}
		}
		// 3) Сообщества, где юзер состоит
		rows2, err2 := db.Query(`
			SELECT co.id, co.name, COALESCE(co.avatar_url, ''), cm.role
			FROM communities co
			JOIN community_members cm ON cm.community_id = co.id
			WHERE cm.user_id = $1 AND co.is_deleted = FALSE
			ORDER BY co.name
		`, userID)
		if err2 == nil {
			defer rows2.Close()
			for rows2.Next() {
				var t target
				var role string
				if err := rows2.Scan(&t.ID, &t.Name, &t.Avatar, &role); err == nil {
					t.Type = "community"
					switch role {
					case "owner":
						t.Subtitle = "Владелец сообщества"
					case "admin":
						t.Subtitle = "Админ сообщества"
					default:
						t.Subtitle = "Участник сообщества"
					}
					targets = append(targets, t)
				}
			}
		}

		// 4) Друзья — для отправки в личный чат
		rows3, err3 := db.Query(`
			SELECT u.id, COALESCE(u.public_id, ''), COALESCE(NULLIF(u.full_name,''), u.email), COALESCE(u.avatar_url, '')
			FROM friend_requests fr
			JOIN users u ON u.id = CASE WHEN fr.requester_id = $1 THEN fr.addressee_id ELSE fr.requester_id END
			WHERE (fr.requester_id = $1 OR fr.addressee_id = $1) AND fr.status = 'accepted' AND u.is_deleted = FALSE
			ORDER BY u.full_name
			LIMIT 50
		`, userID)
		if err3 == nil {
			defer rows3.Close()
			for rows3.Next() {
				var t target
				if err := rows3.Scan(&t.ID, &t.PublicID, &t.Name, &t.Avatar); err == nil {
					t.Type = "friend"
					t.Subtitle = "Отправить в чат"
					targets = append(targets, t)
				}
			}
		}

		writeJSON(w, http.StatusOK, map[string]any{"targets": targets})
	})

