	mux.HandleFunc("/api/chat/conversations/", func(w http.ResponseWriter, r *http.Request) {
		userID, ok := authenticatedUserID(w, r, sessions)
		if !ok {
			return
		}
		chatPresence.touch(userID)
		tail := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/chat/conversations/"), "/")
		parts := strings.Split(tail, "/")
		if len(parts) == 0 || parts[0] == "" {
			writeError(w, http.StatusBadRequest, "Некорректный путь")
			return
		}
		if parts[0] == "community" && len(parts) == 2 && r.Method == http.MethodPost {
			communityID, err := strconv.ParseInt(parts[1], 10, 64)
			if err != nil || communityID <= 0 {
				writeError(w, http.StatusBadRequest, "Некорректный id сообщества")
				return
			}
			item, err := getOrCreateCommunityConversation(db, r, communityID, userID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"conversation": item})
			return
		}
		publicID := parts[0]
		if len(parts) == 1 && r.Method == http.MethodDelete {
			// Удалить участие текущего юзера в этом чате (мягкое удаление — у собеседника остаётся)
			res, err := db.Exec(`
				DELETE FROM chat_participants
				WHERE user_id=$1 AND conversation_id=(SELECT id FROM chat_conversations WHERE public_id=$2)
			`, userID, publicID)
			if err != nil {
				log.Printf("[chat] delete participation: %v", err)
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			n, _ := res.RowsAffected()
			if n == 0 {
				writeError(w, http.StatusNotFound, "Чат не найден")
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}

		// GET /api/chat/conversations/{publicID}/members — список участников группы
		if len(parts) == 2 && parts[1] == "members" && r.Method == http.MethodGet {
			rows, err := db.Query(`
				SELECT u.id, COALESCE(u.public_id, ''), COALESCE(NULLIF(u.full_name,''), u.email), COALESCE(u.avatar_url, ''), p.role, p.joined_at
				FROM chat_participants p
				JOIN chat_conversations c ON c.id = p.conversation_id
				JOIN users u ON u.id = p.user_id
				WHERE c.public_id = $1 AND p.participant_kind = 'user'
				ORDER BY CASE p.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END, u.full_name
			`, publicID)
			if err != nil {
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			defer rows.Close()
			type member struct {
				ID       int64     `json:"id"`
				PublicID string    `json:"public_id"`
				Name     string    `json:"name"`
				Avatar   string    `json:"avatar,omitempty"`
				Role     string    `json:"role"`
				JoinedAt time.Time `json:"joined_at"`
			}
			var out []member
			for rows.Next() {
				var m member
				if err := rows.Scan(&m.ID, &m.PublicID, &m.Name, &m.Avatar, &m.Role, &m.JoinedAt); err == nil {
					out = append(out, m)
				}
			}
			writeJSON(w, http.StatusOK, map[string]any{"members": out})
			return
		}
		if len(parts) == 1 && r.Method == http.MethodPatch {
			var myRole string
			if err := db.QueryRow(`SELECT p.role FROM chat_participants p JOIN chat_conversations c ON c.id = p.conversation_id WHERE c.public_id = $1 AND p.user_id = $2`, publicID, userID).Scan(&myRole); err != nil {
				writeError(w, http.StatusNotFound, "Чат не найден")
				return
			}
			if myRole != "owner" && myRole != "admin" {
				writeError(w, http.StatusForbidden, "Только владелец или админ может менять группу")
				return
			}
			var req struct {
				Title     *string `json:"title"`
				AvatarURL *string `json:"avatar_url"`
			}
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			if req.Title != nil {
				t := strings.TrimSpace(*req.Title)
				if utf8.RuneCountInString(t) < 1 || utf8.RuneCountInString(t) > 100 {
					writeError(w, http.StatusBadRequest, "Название: 1–100 символов")
					return
				}
				if _, err := db.Exec(`UPDATE chat_conversations SET title=$1 WHERE public_id=$2`, t, publicID); err != nil {
					writeError(w, http.StatusInternalServerError, "Ошибка")
					return
				}
			}
			if req.AvatarURL != nil {
				if _, err := db.Exec(`UPDATE chat_conversations SET avatar_url=$1 WHERE public_id=$2`, *req.AvatarURL, publicID); err != nil {
					writeError(w, http.StatusInternalServerError, "Ошибка")
					return
				}
			}
			writeJSON(w, http.StatusOK, map[string]any{"ok": true})
			return
		}
		if len(parts) == 2 && parts[1] == "members" && r.Method == http.MethodPost {
			var myRole string
			if err := db.QueryRow(`SELECT p.role FROM chat_participants p JOIN chat_conversations c ON c.id = p.conversation_id WHERE c.public_id = $1 AND p.user_id = $2`, publicID, userID).Scan(&myRole); err != nil {
				writeError(w, http.StatusNotFound, "Чат не найден")
				return
			}
			if myRole != "owner" && myRole != "admin" {
				writeError(w, http.StatusForbidden, "Только владелец или админ может добавлять участников")
				return
			}
			var req struct {
				UserPublicID string `json:"user_public_id"`
			}
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			var newUserID int64
			if err := db.QueryRow(`SELECT id FROM users WHERE public_id=$1 AND is_deleted=FALSE`, req.UserPublicID).Scan(&newUserID); err != nil {
				writeError(w, http.StatusNotFound, "Пользователь не найден")
				return
			}
			var convID int64
			if err := db.QueryRow(`SELECT id FROM chat_conversations WHERE public_id=$1`, publicID).Scan(&convID); err != nil {
				writeError(w, http.StatusNotFound, "Чат не найден")
				return
			}
			if _, err := db.Exec(`INSERT INTO chat_participants (conversation_id, user_id, role, participant_kind, participant_id) VALUES ($1, $2, 'member', 'user', $2) ON CONFLICT (conversation_id, user_id) DO NOTHING`, convID, newUserID); err != nil {
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"ok": true})
			return
		}
		if len(parts) == 3 && parts[1] == "members" && r.Method == http.MethodDelete {
			var myRole string
			if err := db.QueryRow(`SELECT p.role FROM chat_participants p JOIN chat_conversations c ON c.id = p.conversation_id WHERE c.public_id = $1 AND p.user_id = $2`, publicID, userID).Scan(&myRole); err != nil {
				writeError(w, http.StatusNotFound, "Чат не найден")
				return
			}
			if myRole != "owner" && myRole != "admin" {
				writeError(w, http.StatusForbidden, "Только владелец или админ может удалять")
				return
			}
			targetPublicID := parts[2]
			var targetUserID int64
			if err := db.QueryRow(`SELECT id FROM users WHERE public_id=$1`, targetPublicID).Scan(&targetUserID); err != nil {
				writeError(w, http.StatusNotFound, "Пользователь не найден")
				return
			}
			var targetRole string
			_ = db.QueryRow(`SELECT p.role FROM chat_participants p JOIN chat_conversations c ON c.id = p.conversation_id WHERE c.public_id = $1 AND p.user_id = $2`, publicID, targetUserID).Scan(&targetRole)
			if targetRole == "owner" {
				writeError(w, http.StatusBadRequest, "Нельзя удалить владельца группы")
				return
			}
			if _, err := db.Exec(`DELETE FROM chat_participants WHERE user_id=$1 AND conversation_id=(SELECT id FROM chat_conversations WHERE public_id=$2)`, targetUserID, publicID); err != nil {
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"ok": true})
			return
		}

		if len(parts) == 1 && r.Method == http.MethodGet {
			item, err := getConversationByPublicID(db, userID, publicID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			if item.Type == "direct" {
				otherID, _ := getUserIDByPublicID(db, item.OtherPublicID)
				item.IsOnline = chatPresence.isOnline(otherID)
			}
			writeJSON(w, http.StatusOK, map[string]any{"conversation": item})
			return
		}
		if len(parts) == 2 && parts[1] == "messages" {
			switch r.Method {
			case http.MethodGet:
				limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
				before, _ := strconv.ParseInt(r.URL.Query().Get("before_id"), 10, 64)
				msgs, err := listMessages(db, userID, publicID, limit, before)
				if err != nil {
					handleChatError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"messages": msgs})
			case http.MethodPost:
				if !chatMessageRateLimiter.Allow(fmt.Sprintf("chat-msg:%d", userID)) {
					writeError(w, http.StatusTooManyRequests, "Слишком часто")
					return
				}
				var req sendMessageRequest
				if err := decodeJSON(w, r, &req); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				// Контекст отправителя берём из participant_kind/participant_id текущего юзера в этом диалоге.
				var pKind string
				var pID int64
				if err := db.QueryRow(`SELECT p.participant_kind, p.participant_id FROM chat_participants p JOIN chat_conversations c ON c.id = p.conversation_id WHERE c.public_id=$1 AND p.user_id=$2`, publicID, userID).Scan(&pKind, &pID); err != nil {
					writeError(w, http.StatusNotFound, "Диалог не найден")
					return
				}
				switch pKind {
				case "company":
					req.SenderCompanyID = pID
					req.SenderCommunityID = 0
					_, isOwner, _, _, _, canChat, err := companyMemberRights(db, pID, userID)
					if err != nil {
						writeError(w, http.StatusInternalServerError, "Ошибка проверки прав")
						return
					}
					if !isOwner && !canChat {
						writeError(w, http.StatusForbidden, "У вас нет права отвечать от лица компании")
						return
					}
				case "community":
					req.SenderCommunityID = pID
					req.SenderCompanyID = 0
				default:
					req.SenderCompanyID = 0
					req.SenderCommunityID = 0
				}
				msg, err := sendMessage(db, userID, publicID, req)
				if err != nil {
					handleChatError(w, err)
					return
				}
				writeJSON(w, http.StatusCreated, map[string]any{"message": msg})
			default:
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			}
			return
		}
		if len(parts) == 2 && parts[1] == "typing" {
			if r.Method == http.MethodPost {
				if !chatTypingRateLimiter.Allow(fmt.Sprintf("chat-typing:%d", userID)) {
					writeError(w, http.StatusTooManyRequests, "Слишком часто")
					return
				}
				var req typingRequest
				if err := decodeJSON(w, r, &req); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				if err := setTyping(db, userID, publicID, req.IsTyping); err != nil {
					handleChatError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			if r.Method == http.MethodGet {
				items, err := listTyping(db, userID, publicID)
				if err != nil {
					handleChatError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"users": items})
				return
			}
		}
		if len(parts) == 2 && parts[1] == "read" && r.Method == http.MethodPost {
			var req struct {
				MessageID int64 `json:"message_id"`
			}
			_ = decodeJSON(w, r, &req)
			// Если message_id не указан — берём максимальный из чата
			if req.MessageID == 0 {
				_ = db.QueryRow(`SELECT COALESCE(MAX(m.id),0) FROM chat_messages m JOIN chat_conversations c ON c.id=m.conversation_id WHERE c.public_id=$1 AND m.is_deleted=FALSE`, publicID).Scan(&req.MessageID)
			}
			if req.MessageID == 0 {
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			_, err := db.Exec(`
				UPDATE chat_participants
				SET last_read_message_id = GREATEST(last_read_message_id, $1),
				    last_read_at = NOW()
				WHERE user_id = $2
				  AND conversation_id = (SELECT id FROM chat_conversations WHERE public_id=$3)
			`, req.MessageID, userID, publicID)
			if err != nil {
				log.Printf("[chat] mark read: %v", err)
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		if len(parts) == 2 && parts[1] == "attachments" && r.Method == http.MethodGet {
			// Проверка — юзер участник чата
			var convID int64
			if err := db.QueryRow(`
				SELECT c.id FROM chat_conversations c
				JOIN chat_participants p ON p.conversation_id=c.id
				WHERE c.public_id=$1 AND p.user_id=$2
			`, publicID, userID).Scan(&convID); err != nil {
				if err == sql.ErrNoRows {
					writeError(w, http.StatusNotFound, "Чат не найден")
					return
				}
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			rows, err := db.Query(`
				SELECT id, attachment_url, attachment_name, attachment_type, attachment_size, content, created_at
				FROM chat_messages
				WHERE conversation_id=$1 AND is_deleted=FALSE
				  AND (attachment_url<>'' OR content ~ 'https?://')
				ORDER BY id DESC
				LIMIT 200
			`, convID)
			if err != nil {
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			defer rows.Close()
			images := []map[string]any{}
			files := []map[string]any{}
			audio := []map[string]any{}
			links := []map[string]any{}
			urlRe := regexp.MustCompile(`https?://[^\s]+`)
			for rows.Next() {
				var id int64
				var aURL, aName, aType, content string
				var aSize int64
				var createdAt time.Time
				if err := rows.Scan(&id, &aURL, &aName, &aType, &aSize, &content, &createdAt); err != nil {
					continue
				}
				if aURL != "" {
					item := map[string]any{
						"id": id, "url": aURL, "name": aName, "type": aType,
						"size": aSize, "created_at": createdAt,
					}
					switch {
					case strings.HasPrefix(aType, "image/"):
						images = append(images, item)
					case strings.HasPrefix(aType, "audio/"):
						audio = append(audio, item)
					default:
						files = append(files, item)
					}
				}
				if content != "" {
					for _, m := range urlRe.FindAllString(content, -1) {
						links = append(links, map[string]any{
							"id": id, "url": m, "created_at": createdAt,
						})
					}
				}
			}
			writeJSON(w, http.StatusOK, map[string]any{
				"images": images, "files": files, "audio": audio, "links": links,
			})
			return
		}
		if len(parts) == 2 && parts[1] == "read" && r.Method == http.MethodPost {
			var req markReadRequest
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			if _, err := db.Exec(`UPDATE chat_participants p SET last_read_message_id=GREATEST(last_read_message_id,$1) FROM chat_conversations c WHERE c.id=p.conversation_id AND c.public_id=$2 AND p.user_id=$3`, req.MessageID, publicID, userID); err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		if len(parts) == 2 && parts[1] == "pin" && r.Method == http.MethodPost {
			var req toggleBoolRequest
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			_, err := db.Exec(`UPDATE chat_participants p SET pinned=$1 FROM chat_conversations c WHERE c.id=p.conversation_id AND c.public_id=$2 AND p.user_id=$3`, req.Pinned, publicID, userID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		if len(parts) == 2 && parts[1] == "mute" && r.Method == http.MethodPost {
			var req toggleBoolRequest
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			_, err := db.Exec(`UPDATE chat_participants p SET muted=$1 FROM chat_conversations c WHERE c.id=p.conversation_id AND c.public_id=$2 AND p.user_id=$3`, req.Muted, publicID, userID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		if len(parts) == 2 && parts[1] == "leave" && r.Method == http.MethodPost {
			res, err := db.Exec(`DELETE FROM chat_participants p USING chat_conversations c WHERE c.id=p.conversation_id AND c.public_id=$1 AND p.user_id=$2 AND c.type IN ('group','community')`, publicID, userID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			n, _ := res.RowsAffected()
			if n == 0 {
				writeError(w, http.StatusBadRequest, "Нельзя выйти из direct-диалога")
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		if len(parts) == 2 && parts[1] == "search" && r.Method == http.MethodGet {
			items, err := searchInConversation(db, userID, publicID, r.URL.Query().Get("q"))
			if err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"messages": items})
			return
		}
		writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
	})

	mux.HandleFunc("/api/chat/messages/", func(w http.ResponseWriter, r *http.Request) {
		userID, ok := authenticatedUserID(w, r, sessions)
		if !ok {
			return
		}
		chatPresence.touch(userID)
		idStr := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/chat/messages/"), "/")
		msgID, _ := strconv.ParseInt(idStr, 10, 64)
		// Для под-путей вида {id}/react msgID парсится внутри соответствующей ветки —
		// здесь не отсекаем (иначе react/прочие суффиксы получат «Некорректный id»).
		isSuffixRoute := strings.Contains(idStr, "/")
		if msgID == 0 && !isSuffixRoute {
			writeError(w, http.StatusBadRequest, "Некорректный id")
			return
		}
		if r.Method == http.MethodDelete {
			_, err := db.Exec(`UPDATE chat_messages SET is_deleted=TRUE,content='',attachment_url='',attachment_name='',attachment_type='',attachment_size=0 WHERE id=$1 AND author_id=$2`, msgID, userID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		if r.Method == http.MethodPatch {
			var req editMessageRequest
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			_, err := db.Exec(`UPDATE chat_messages SET content=$1,is_edited=TRUE,edited_at=NOW() WHERE id=$2 AND author_id=$3 AND created_at >= NOW()-INTERVAL '15 minutes'`, strings.TrimSpace(req.Content), msgID, userID)
			if err != nil {
				handleChatError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			return
		}
		// POST /api/chat/messages/{id}/react — поставить/снять/сменить реакцию
		if r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/react") {
			realID := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/chat/messages/"), "/")
			realID = strings.TrimSuffix(realID, "/react")
			msgID, _ = strconv.ParseInt(strings.Trim(realID, "/"), 10, 64)
			if msgID == 0 {
				writeError(w, http.StatusBadRequest, "Некорректный id")
				return
			}
			var req struct {
				Emoji string `json:"emoji"`
			}
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			emoji := strings.TrimSpace(req.Emoji)
			if emoji == "" || utf8.RuneCountInString(emoji) > 8 {
				writeError(w, http.StatusBadRequest, "Некорректный emoji")
				return
			}
			// Проверяем, что сообщение существует и юзер — участник диалога; берём conv и автора
			var convID, authorID int64
			err := db.QueryRow(`
				SELECT m.conversation_id, m.author_id
				FROM chat_messages m
				JOIN chat_participants p ON p.conversation_id = m.conversation_id AND p.user_id = $2
				WHERE m.id = $1 AND m.is_deleted = FALSE`, msgID, userID).Scan(&convID, &authorID)
			if err != nil {
				writeError(w, http.StatusNotFound, "Сообщение не найдено")
				return
			}
			// Текущая реакция юзера на это сообщение
			var existing string
			_ = db.QueryRow(`SELECT emoji FROM message_reactions WHERE message_id=$1 AND user_id=$2`, msgID, userID).Scan(&existing)
			added := false
			if existing == emoji {
				// тот же — снять
				_, _ = db.Exec(`DELETE FROM message_reactions WHERE message_id=$1 AND user_id=$2`, msgID, userID)
			} else {
				// поставить/сменить (UNIQUE message_id+user_id → ON CONFLICT обновляем emoji)
				_, _ = db.Exec(`
					INSERT INTO message_reactions (message_id, user_id, emoji)
					VALUES ($1, $2, $3)
					ON CONFLICT (message_id, user_id) DO UPDATE SET emoji = EXCLUDED.emoji, created_at = NOW()`,
					msgID, userID, emoji)
				added = true
			}
			// Свежий агрегат для рассылки
			aggMap := loadReactionsFor(db, userID, []int64{msgID})
			reactions := aggMap[msgID]
			if reactions == nil {
				reactions = []reactionAgg{}
			}
			// Узнаём public_id диалога для фронта
			var convPublicID string
			_ = db.QueryRow(`SELECT public_id FROM chat_conversations WHERE id=$1`, convID).Scan(&convPublicID)
			// WS-рассылка всем участникам
			go func() {
				rows, err := db.Query(`SELECT user_id FROM chat_participants WHERE conversation_id=$1`, convID)
				if err != nil {
					return
				}
				defer rows.Close()
				for rows.Next() {
					var uid int64
					if err := rows.Scan(&uid); err != nil {
						continue
					}
					// reactions персональны (флаг mine) — но для простоты шлём агрегат без mine;
					// клиент пересчитает mine по своему действию. Отправляем счётчики.
					wsHub.Send(uid, "chat:reaction", map[string]any{
						"conversation_public_id": convPublicID,
						"message_id":             msgID,
						"reactions":              reactions,
					})
				}
			}()
			// Уведомление автору (если реакция добавлена, не своё сообщение)
			if added && authorID != 0 && authorID != userID {
				var actorName string
				_ = db.QueryRow(`SELECT COALESCE(full_name, handle, '') FROM users WHERE id=$1`, userID).Scan(&actorName)
				_ = createNotification(db, createNotificationParams{
					RecipientID:    authorID,
					ActorID:        userID,
					Type:           "reaction",
					SourceType:     "chat_message",
					SourceID:       msgID,
					SourcePublicID: convPublicID,
					Title:          actorName + " отреагировал(а) " + emoji,
					Preview:        "",
				})
			}
			writeJSON(w, http.StatusOK, map[string]any{"reactions": reactions})
			return
		}
		writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
	})

	mux.HandleFunc("/api/chat/presence/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		_, ok := authenticatedUserID(w, r, sessions)
		if !ok {
			return
		}
		pid := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/chat/presence/"), "/")
		uid, err := getUserIDByPublicID(db, pid)
		if err != nil {
			handleChatError(w, err)
			return
		}
		writeJSON(w, http.StatusOK, map[string]any{"is_online": chatPresence.isOnline(uid)})
	})
	mux.HandleFunc("/api/communities", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			authUserID, hasAuth := optionalAuthenticatedUserID(r, sessions)
			communities, err := listCommunities(db, authUserID, hasAuth, communityListFilters{
				Privacy:    r.URL.Query().Get("privacy"),
				Category:   r.URL.Query().Get("category"),
				Region:     r.URL.Query().Get("region"),
				Query:      r.URL.Query().Get("q"),
				Tab:        r.URL.Query().Get("tab"),
				RoleFilter: r.URL.Query().Get("role_filter"),
			})
			if err != nil {
				handleCommunityError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"communities": communities})
		case http.MethodPost:
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if !communityCreateRateLimiter.Allow(fmt.Sprintf("community-create:%d", userID)) {
				writeError(w, http.StatusTooManyRequests, "Слишком много созданий сообществ, попробуйте позже")
				return
			}

			var req createCommunityRequest
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}

			created, err := createCommunity(db, userID, req)
			if err != nil {
				handleCommunityError(w, err)
				return
			}
			writeJSON(w, http.StatusCreated, map[string]any{"community": created})
		default:
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
		}
	})

	mux.HandleFunc("/api/communities/", func(w http.ResponseWriter, r *http.Request) {
		tail := strings.Trim(strings.TrimPrefix(r.URL.Path, "/api/communities/"), "/")
		if tail == "" {
			writeError(w, http.StatusNotFound, "Не найдено")
			return
		}
		parts := strings.Split(tail, "/")
		communityID, ok := parseCommunityID(parts[0])
		if !ok {
			var resolvedID int64
			if err := db.QueryRow(`SELECT id FROM communities WHERE slug = $1 AND is_deleted = FALSE`, parts[0]).Scan(&resolvedID); err == nil && resolvedID > 0 {
				communityID = resolvedID
				ok = true
			}
		}
		if !ok {
			writeError(w, http.StatusBadRequest, "Некорректный id сообщества")
			return
		}
		authUserID, hasAuth := optionalAuthenticatedUserID(r, sessions)
		if len(parts) == 1 {
			switch r.Method {
			case http.MethodGet:
				item, err := getCommunityByID(db, communityID, authUserID, hasAuth)
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"community": item})
			case http.MethodPatch:
				userID, ok := authenticatedUserID(w, r, sessions)
				if !ok {
					return
				}
				var req updateCommunityRequest
				if err := decodeJSON(w, r, &req); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				item, err := updateCommunity(db, communityID, userID, req)
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"community": item})
			case http.MethodDelete:
				userID, ok := authenticatedUserID(w, r, sessions)
				if !ok {
					return
				}
				if err := deleteCommunity(db, communityID, userID); err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
			default:
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			}
			return
		}
		switch parts[1] {
		case "join":
			if r.Method != http.MethodPost {
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
				return
			}
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if err := joinCommunity(db, communityID, userID); err != nil {
				handleCommunityError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
		case "leave":
			if r.Method != http.MethodPost {
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
				return
			}
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if err := leaveCommunity(db, communityID, userID); err != nil {
				handleCommunityError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
		case "join-requests":
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if len(parts) == 2 && r.Method == http.MethodPost {
				if !communityJoinRequestRateLimiter.Allow(fmt.Sprintf("community-join-request:%d", userID)) {
					writeError(w, http.StatusTooManyRequests, "Слишком много заявок, попробуйте позже")
					return
				}
				var body joinRequestBody
				if err := decodeJSON(w, r, &body); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				if err := createJoinRequest(db, communityID, userID, body.Message); err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusCreated, map[string]string{"status": "ok"})
				return
			}
			if len(parts) == 2 && r.Method == http.MethodGet {
				items, err := listJoinRequests(db, communityID, userID)
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"requests": items})
				return
			}
			if len(parts) == 3 && parts[2] == "mine" && r.Method == http.MethodDelete {
				if err := cancelMyJoinRequest(db, communityID, userID); err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			if len(parts) == 4 && r.Method == http.MethodPost && (parts[3] == "approve" || parts[3] == "reject") {
				requestID, ok := parseCommunityID(parts[2])
				if !ok {
					writeError(w, http.StatusBadRequest, "Некорректный id заявки")
					return
				}
				var err error
				if parts[3] == "approve" {
					err = approveJoinRequest(db, communityID, requestID, userID)
				} else {
					err = rejectJoinRequest(db, communityID, requestID, userID)
				}
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
		case "projects":
			if r.Method != http.MethodGet {
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
				return
			}
			limit := parseLimit(r.URL.Query().Get("limit"), 30, 100)
			rows, err := db.Query(`
				SELECT p.public_id, p.title, p.description, p.category, p.status,
				       COALESCE(p.cover_color, ''), COALESCE(p.cover_url, ''),
				       p.created_at, p.updated_at,
				       u.public_id, COALESCE(u.full_name, u.handle, '')
				FROM projects p
				JOIN users u ON u.id = p.owner_id
				WHERE p.community_id = $1 AND p.is_deleted = FALSE
				ORDER BY p.created_at DESC
				LIMIT $2`, communityID, limit)
			if err != nil {
				writeError(w, http.StatusInternalServerError, "Ошибка БД")
				return
			}
			defer rows.Close()
			items := []map[string]any{}
			for rows.Next() {
				var pid, title, desc, cat, status, coverColor, coverURL, ownerPid, ownerName string
				var createdAt, updatedAt time.Time
				if err := rows.Scan(&pid, &title, &desc, &cat, &status, &coverColor, &coverURL, &createdAt, &updatedAt, &ownerPid, &ownerName); err != nil {
					continue
				}
				items = append(items, map[string]any{
					"public_id":       pid,
					"title":           title,
					"description":     desc,
					"category":        cat,
					"status":          status,
					"cover_color":     coverColor,
					"cover_url":       coverURL,
					"created_at":      createdAt,
					"updated_at":      updatedAt,
					"owner_public_id": ownerPid,
					"owner_name":      ownerName,
				})
			}
			writeJSON(w, http.StatusOK, map[string]any{"projects": items})
			return
		case "events":
			if r.Method != http.MethodGet {
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
				return
			}
			limit := parseLimit(r.URL.Query().Get("limit"), 30, 100)
			rows, err := db.Query(`
				SELECT e.public_id, e.title, COALESCE(e.description, ''),
				       e.format, e.starts_at, e.ends_at,
				       COALESCE(e.city, ''), COALESCE(e.cover_url, ''),
				       e.views_count, e.registered_count
				FROM events e
				WHERE e.community_id = $1 AND e.is_deleted = FALSE
				ORDER BY e.starts_at DESC
				LIMIT $2`, communityID, limit)
			if err != nil {
				log.Printf("[community/events] %v", err)
				writeError(w, http.StatusInternalServerError, "Ошибка БД")
				return
			}
			defer rows.Close()
			items := []map[string]any{}
			for rows.Next() {
				var pid, title, desc, format, city, coverURL string
				var startsAt, endsAt time.Time
				var viewsCount, attendeesCount int
				if err := rows.Scan(&pid, &title, &desc, &format, &startsAt, &endsAt, &city, &coverURL, &viewsCount, &attendeesCount); err != nil {
					continue
				}
				items = append(items, map[string]any{
					"public_id":       pid,
					"title":           title,
					"description":     desc,
					"format":          format,
					"starts_at":       startsAt,
					"ends_at":         endsAt,
					"city":            city,
					"cover_url":       coverURL,
					"views_count":     viewsCount,
					"attendees_count": attendeesCount,
				})
			}
			writeJSON(w, http.StatusOK, map[string]any{"events": items})
			return
		case "resumes":
			if r.Method != http.MethodGet {
				writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
				return
			}
			limit := parseLimit(r.URL.Query().Get("limit"), 30, 100)
			rows, err := db.Query(`
				SELECT r.public_id, r.title, COALESCE(r.about, ''),
				       r.category, r.city, r.work_format,
				       r.salary_from, r.experience_years,
				       r.created_at,
				       u.public_id, COALESCE(u.full_name, u.handle, '')
				FROM resumes r
				JOIN users u ON u.id = r.author_user_id
				WHERE r.community_id = $1 AND r.deleted_at IS NULL
				ORDER BY r.created_at DESC
				LIMIT $2`, communityID, limit)
			if err != nil {
				log.Printf("[community/resumes] %v", err)
				writeError(w, http.StatusInternalServerError, "Ошибка БД")
				return
			}
			defer rows.Close()
			items := []map[string]any{}
			for rows.Next() {
				var pid, title, about, cat, city, workFormat, authorPid, authorName string
				var salaryFrom sql.NullInt64
				var expYears int
				var createdAt time.Time
				if err := rows.Scan(&pid, &title, &about, &cat, &city, &workFormat, &salaryFrom, &expYears, &createdAt, &authorPid, &authorName); err != nil {
					continue
				}
				salary := int64(0)
				if salaryFrom.Valid {
					salary = salaryFrom.Int64
				}
				items = append(items, map[string]any{
					"public_id":        pid,
					"title":            title,
					"about":            about,
					"category":         cat,
					"city":             city,
					"work_format":      workFormat,
					"salary_from":      salary,
					"experience_years": expYears,
					"created_at":       createdAt,
					"author_public_id": authorPid,
					"author_name":      authorName,
				})
			}
			writeJSON(w, http.StatusOK, map[string]any{"resumes": items})
			return
		case "members":
			// PATCH /api/communities/{id}/members/{user_id} — смена role
			if len(parts) == 3 && r.Method == http.MethodPatch {
				targetUserID, err := strconv.ParseInt(parts[2], 10, 64)
				if err != nil || targetUserID <= 0 {
					writeError(w, http.StatusBadRequest, "Некорректный user_id")
					return
				}
				userID, ok := authenticatedUserID(w, r, sessions)
				if !ok {
					return
				}
				// Только owner может менять role
				myRole, err := getUserCommunityRole(db, communityID, userID)
				if err != nil || myRole != "owner" {
					writeError(w, http.StatusForbidden, "Только владелец сообщества может менять роли")
					return
				}
				// Owner не может менять свою role
				if targetUserID == userID {
					writeError(w, http.StatusBadRequest, "Нельзя изменить собственную роль")
					return
				}
				var req struct {
					Role string `json:"role"`
				}
				if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				if req.Role != "member" && req.Role != "moderator" {
					writeError(w, http.StatusBadRequest, "Допустимые роли: member, moderator")
					return
				}
				// Проверим что target уже состоит в сообществе и не owner
				var targetCurrentRole string
				if err := db.QueryRow(
					`SELECT role FROM community_members WHERE community_id=$1 AND user_id=$2`,
					communityID, targetUserID,
				).Scan(&targetCurrentRole); err != nil {
					if err == sql.ErrNoRows {
						writeError(w, http.StatusNotFound, "Пользователь не состоит в сообществе")
					} else {
						writeError(w, http.StatusInternalServerError, "Ошибка БД")
					}
					return
				}
				if targetCurrentRole == "owner" {
					writeError(w, http.StatusBadRequest, "Нельзя изменить роль владельца")
					return
				}
				if _, err := db.Exec(
					`UPDATE community_members SET role=$1 WHERE community_id=$2 AND user_id=$3`,
					req.Role, communityID, targetUserID,
				); err != nil {
					writeError(w, http.StatusInternalServerError, "Не удалось обновить роль")
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"role": req.Role})
				return
			}
			if len(parts) == 2 && r.Method == http.MethodGet {
				limit := parseLimit(r.URL.Query().Get("limit"), 50, 200)
				offset := parseLimit(r.URL.Query().Get("offset"), 0, 100000)
				items, err := listCommunityMembers(db, communityID, authUserID, hasAuth, limit, offset)
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"members": items})
				return
			}
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if len(parts) == 4 && parts[3] == "role" && r.Method == http.MethodPut {
				var req changeRoleRequest
				if err := decodeJSON(w, r, &req); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				if err := changeCommunityRole(db, communityID, parts[2], req.Role, userID); err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			if len(parts) == 3 && r.Method == http.MethodDelete {
				if err := kickCommunityMember(db, communityID, parts[2], userID); err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
		case "posts":
			if len(parts) == 2 && r.Method == http.MethodGet {
				limit := parseLimit(r.URL.Query().Get("limit"), 20, 100)
				beforeID := parseIDOrZero(r.URL.Query().Get("before_id"))
				items, nextCursor, err := listCommunityPosts(db, communityID, authUserID, hasAuth, limit, beforeID)
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]any{"posts": items, "next_cursor": nextCursor})
				return
			}
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if len(parts) == 2 && r.Method == http.MethodPost {
				if !communityPostRateLimiter.Allow(fmt.Sprintf("community-post:%d", userID)) {
					writeError(w, http.StatusTooManyRequests, "Слишком много публикаций в сообществах, попробуйте позже")
					return
				}
				var req createPostRequest
				if err := decodeJSON(w, r, &req); err != nil {
					writeError(w, http.StatusBadRequest, "Некорректный JSON")
					return
				}
				item, err := createCommunityPost(db, communityID, userID, req)
				if err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusCreated, map[string]any{"post": item})
				return
			}
			if len(parts) == 3 && r.Method == http.MethodDelete {
				if err := deleteCommunityPost(db, communityID, parts[2], userID); err != nil {
					handleCommunityError(w, err)
					return
				}
				writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
				return
			}
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
		default:
			writeError(w, http.StatusNotFound, "Не найдено")
		}
	})

	mux.HandleFunc("/api/events", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			authUserID, hasAuth := optionalAuthenticatedUserID(r, sessions)
			items, nextCursor, err := listEvents(db, authUserID, hasAuth, eventFilterFromRequest(r))
			if err != nil {
				handleEventError(w, err)
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"events": items, "next_cursor": nextCursor})
		case http.MethodPost:
			userID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			if !eventCreateLimiter.Allow(fmt.Sprintf("event-create:%d", userID)) {
				writeError(w, http.StatusTooManyRequests, "Слишком много попыток")
				return
			}
			var req createEventRequest
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			resolvedCompanyID, err := resolveActiveCompanyID(db, r, userID, derefInt64(req.CompanyID))
			if err != nil {
				writeJSON(w, http.StatusForbidden, map[string]any{"error": "вы не состоите в этой компании"})
				return
			}
			var resolvedCommunityID int64
			if resolvedCompanyID == 0 {
				reqCommID := int64(0)
				if req.CommunityID != nil {
					reqCommID = *req.CommunityID
				}
				resolvedCommunityID, err = resolveActiveCommunityID(db, r, userID, reqCommID)
				if err != nil {
					writeJSON(w, http.StatusForbidden, map[string]any{"error": "вы не можете публиковать от лица этого сообщества"})
					return
				}
			}
			req.CompanyID = nil
			if resolvedCompanyID > 0 {
				req.CompanyID = &resolvedCompanyID
			}
			req.CommunityID = nil
			if resolvedCommunityID > 0 {
				req.CommunityID = &resolvedCommunityID
			}
			item, err := createEvent(db, userID, req)
			if err != nil {
				handleEventError(w, err)
				return
			}
			writeJSON(w, http.StatusCreated, map[string]any{"event": item})
		default:
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
		}
	})

