	mux.HandleFunc("/api/posts/trends", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		rows, err := db.Query(`
			SELECT tag, COUNT(*) AS cnt
			FROM (
				SELECT unnest(tags) AS tag
				FROM posts
				WHERE is_deleted = FALSE
				  AND created_at >= NOW() - INTERVAL '30 days'
			) t
			WHERE tag IS NOT NULL AND length(trim(tag)) > 0
			GROUP BY tag
			ORDER BY cnt DESC
			LIMIT 5
		`)
		if err != nil {
			log.Printf("[trends] %v", err)
			writeError(w, http.StatusInternalServerError, "Ошибка")
			return
		}
		defer rows.Close()
		type trend struct {
			Tag   string `json:"tag"`
			Count int    `json:"count"`
		}
		out := make([]trend, 0)
		for rows.Next() {
			var t trend
			if err := rows.Scan(&t.Tag, &t.Count); err != nil {
				continue
			}
			out = append(out, t)
		}
		w.Header().Set("Cache-Control", "public, max-age=300")
		writeJSON(w, http.StatusOK, map[string]any{"trends": out})
	})

	mux.HandleFunc("/api/posts/top-authors", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		viewerID, _ := optionalAuthenticatedUserID(r, sessions)
		rows, err := db.Query(`
			SELECT u.public_id, u.full_name, COALESCE(u.avatar_url,''),
			       COUNT(p.id) AS posts_count,
			       (EXISTS(SELECT 1 FROM friend_requests fr WHERE fr.requester_id=$1 AND fr.addressee_id=u.id AND fr.status='accepted')
			        OR EXISTS(SELECT 1 FROM friend_requests fr WHERE fr.addressee_id=$1 AND fr.requester_id=u.id AND fr.status='accepted')) AS is_following
			FROM users u
			JOIN posts p ON p.author_id = u.id
			WHERE p.is_deleted = FALSE AND u.is_deleted = FALSE
			  AND p.created_at >= NOW() - INTERVAL '90 days'
			GROUP BY u.id, u.public_id, u.full_name, u.avatar_url
			ORDER BY posts_count DESC
			LIMIT 5
		`, viewerID)
		if err != nil {
			log.Printf("[top-authors] %v", err)
			writeError(w, http.StatusInternalServerError, "Ошибка")
			return
		}
		defer rows.Close()
		type author struct {
			PublicID    string `json:"public_id"`
			Name        string `json:"name"`
			Avatar      string `json:"avatar,omitempty"`
			PostsCount  int    `json:"posts_count"`
			IsFollowing bool   `json:"is_following"`
		}
		out := make([]author, 0)
		for rows.Next() {
			var a author
			if err := rows.Scan(&a.PublicID, &a.Name, &a.Avatar, &a.PostsCount, &a.IsFollowing); err != nil {
				continue
			}
			out = append(out, a)
		}
		w.Header().Set("Cache-Control", "public, max-age=60")
		writeJSON(w, http.StatusOK, map[string]any{"authors": out})
	})

	mux.HandleFunc("/api/posts/top", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}

		period := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("period")))
		if period != "day" && period != "week" {
			period = "week"
		}

		limit := 5
		if l := r.URL.Query().Get("limit"); l != "" {
			if n, err := strconv.Atoi(l); err == nil && n >= 1 && n <= 10 {
				limit = n
			}
		}

		authUserID, hasAuth := optionalAuthenticatedUserID(r, sessions)
		items, err := listTopPosts(db, authUserID, hasAuth, period, limit)
		if err != nil {
			log.Printf("listTopPosts failed: %v", err)
			writeError(w, http.StatusInternalServerError, "Не удалось получить топ постов")
			return
		}
		if items == nil {
			items = []post{}
		}
		for i := range items {
			applyPlatformUpdateAuthorToPost(&items[i])
		}

		w.Header().Set("Cache-Control", "public, max-age=60")
		writeJSON(w, http.StatusOK, map[string]any{
			"posts":  items,
			"period": period,
		})
	})

	// Phase 5 — обновления платформы. Возвращает посты с category='platform-update'.
	// Доступны всем (это публичная новостная лента от LASTOP GROUP).
	// Автор подменяется на LASTOP GROUP через applyPlatformUpdateAuthor.
	mux.HandleFunc("/api/posts/platform-updates", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		limit := 20
		if l := r.URL.Query().Get("limit"); l != "" {
			if n, err := strconv.Atoi(l); err == nil && n > 0 && n <= 50 {
				limit = n
			}
		}
		offset := 0
		if o := r.URL.Query().Get("offset"); o != "" {
			if n, err := strconv.Atoi(o); err == nil && n >= 0 {
				offset = n
			}
		}
		rows, err := db.Query(`
			SELECT p.public_id, p.title, p.content, p.cover_url, p.tags,
			       p.likes_count, p.comments_count, p.views_count,
			       p.created_at, p.updated_at, p.category
			FROM posts p
			WHERE p.is_deleted = FALSE
			  AND p.is_hidden_by_admin = FALSE
			  AND p.category = 'platform-update'
			  AND p.privacy_level = 'public'
			ORDER BY p.created_at DESC
			LIMIT $1 OFFSET $2
		`, limit, offset)
		if err != nil {
			log.Printf("platform-updates list: %v", err)
			writeError(w, http.StatusInternalServerError, "Ошибка загрузки")
			return
		}
		defer rows.Close()
		out := []map[string]any{}
		for rows.Next() {
			var pub, title, content, cat string
			var cover sql.NullString
			var tagsJSON []byte
			var likes, comments, views int
			var created, updated time.Time
			if err := rows.Scan(&pub, &title, &content, &cover, &tagsJSON, &likes, &comments, &views, &created, &updated, &cat); err != nil {
				log.Printf("platform-updates list row scan: %v", err)
				continue
			}
			var tags []string
			_ = json.Unmarshal(tagsJSON, &tags)
			if tags == nil {
				tags = []string{}
			}
			out = append(out, map[string]any{
				"public_id":      pub,
				"title":          title,
				"content":        content,
				"cover_url":      cover.String,
				"tags":           tags,
				"likes_count":    likes,
				"comments_count": comments,
				"views_count":    views,
				"created_at":     created,
				"updated_at":     updated,
				"category":       cat,
				"author":         applyPlatformUpdateAuthor(cat, map[string]any{}),
			})
		}
		writeJSON(w, http.StatusOK, map[string]any{"posts": out})
	})

