	mux.HandleFunc("/api/forum/topics", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			viewerID, _ := optionalAuthenticatedUserID(r, sessions)
			category := strings.TrimSpace(r.URL.Query().Get("category"))
			if category != "" && !validateForumCategory(category) {
				writeError(w, http.StatusBadRequest, "Неизвестная категория")
				return
			}
			limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
			offset, _ := strconv.Atoi(r.URL.Query().Get("offset"))
			topics, err := listForumTopics(db, category, viewerID, limit, offset)
			if err != nil {
				log.Printf("listForumTopics: %v", err)
				writeError(w, http.StatusInternalServerError, "Ошибка")
				return
			}
			writeJSON(w, http.StatusOK, map[string]any{"topics": topics})
		case http.MethodPost:
			actorID, ok := authenticatedUserID(w, r, sessions)
			if !ok {
				return
			}
			var req struct {
				CategoryKey string `json:"category_key"`
				Title       string `json:"title"`
				Content     string `json:"content"`
				CompanyID   int64  `json:"company_id"`
				CommunityID int64  `json:"community_id"`
			}
			if err := decodeJSON(w, r, &req); err != nil {
				writeError(w, http.StatusBadRequest, "Некорректный JSON")
				return
			}
			resolvedCompanyID, err := resolveActiveCompanyID(db, r, actorID, req.CompanyID)
			if err != nil {
				writeJSON(w, http.StatusForbidden, map[string]any{"error": "вы не можете публиковать от лица этой компании"})
				return
			}
			var resolvedCommunityID int64
			if resolvedCompanyID == 0 {
				resolvedCommunityID, err = resolveActiveCommunityID(db, r, actorID, req.CommunityID)
				if err != nil {
					writeJSON(w, http.StatusForbidden, map[string]any{"error": "вы не можете публиковать от лица этого сообщества"})
					return
				}
			}
			topic, err := createForumTopic(db, actorID, req.CategoryKey, req.Title, req.Content, resolvedCompanyID, resolvedCommunityID)
			if err == nil {
				logUserActivity(db, actorID, "forum_topic", "forum_topic", topic.ID, clientIP(r), r.UserAgent())
			}
			if err != nil {
				log.Printf("createForumTopic: %v", err)
				// Phase 4 (19.05) SEC M-7: бизнес-ошибки валидации содержат
				// безопасные для клиента сообщения. Системные (БД, IO) —
				// могут утечь через err.Error() и раскрыть схему БД.
				if errors.Is(err, errValidation) {
					writeError(w, http.StatusBadRequest, err.Error())
					return
				}
				writeError(w, http.StatusInternalServerError, "Не удалось создать тему")
				return
			}
			writeJSON(w, http.StatusCreated, map[string]any{"topic": topic})
		default:
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
		}
	})

