	mux.HandleFunc("/api/admin/communities/", adminAuditMiddleware(db, sessions, func(w http.ResponseWriter, r *http.Request) {
		actorID, ok := requireAdmin(w, r, db, sessions)
		if !ok {
			return
		}
		publicID := strings.TrimPrefix(r.URL.Path, "/api/admin/communities/")
		if publicID == "" {
			writeError(w, http.StatusNotFound, "Не найдено")
			return
		}
		var cid, creatorID int64
		var name, category, descr, region, website, email, phone, avatar, cslug string
		var verified bool
		var created time.Time
		idNum, numErr := strconv.ParseInt(publicID, 10, 64)
		var qErr error
		if numErr == nil && idNum > 0 {
			qErr = db.QueryRow(`
				SELECT id, name, category, COALESCE(description,''), COALESCE(region,''),
				       COALESCE(website,''), COALESCE(email,''), COALESCE(phone,''), COALESCE(avatar_url,''),
				       is_verified, created_at, creator_id, COALESCE(slug,'')
				FROM communities WHERE id=$1 AND is_deleted=FALSE`, idNum).
				Scan(&cid, &name, &category, &descr, &region, &website, &email, &phone, &avatar, &verified, &created, &creatorID, &cslug)
		} else {
			qErr = db.QueryRow(`
				SELECT id, name, category, COALESCE(description,''), COALESCE(region,''),
				       COALESCE(website,''), COALESCE(email,''), COALESCE(phone,''), COALESCE(avatar_url,''),
				       is_verified, created_at, creator_id, COALESCE(slug,'')
				FROM communities WHERE slug=$1 AND is_deleted=FALSE`, publicID).
				Scan(&cid, &name, &category, &descr, &region, &website, &email, &phone, &avatar, &verified, &created, &creatorID, &cslug)
		}
		err := qErr
		if err != nil {
			writeError(w, http.StatusNotFound, "Сообщество не найдено")
			return
		}
		if r.Method == http.MethodGet {
			var members, posts int
			_ = db.QueryRow(`SELECT COUNT(*)::int FROM community_members WHERE community_id=$1`, cid).Scan(&members)
			_ = db.QueryRow(`SELECT COUNT(*)::int FROM posts WHERE author_community_id=$1 AND is_deleted=FALSE`, cid).Scan(&posts)
			var creatorName, creatorEmail string
			_ = db.QueryRow(`SELECT COALESCE(NULLIF(full_name,''), email), email FROM users WHERE id=$1`, creatorID).Scan(&creatorName, &creatorEmail)
			writeJSON(w, http.StatusOK, map[string]any{
				"item": map[string]any{
					"id": cid, "slug": cslug, "name": name, "category": category,
					"description": descr, "region": region, "website": website, "email": email,
					"phone": phone, "avatar_url": avatar, "is_verified": verified,
					"created_at": created.Format(time.RFC3339), "members_count": members, "posts_count": posts,
					"creator_name": creatorName, "creator_email": creatorEmail,
				},
			})
			return
		}
		if r.Method == http.MethodPost {
			var req struct {
				Verified bool `json:"verified"`
			}
			if json.NewDecoder(r.Body).Decode(&req) != nil {
				writeError(w, http.StatusBadRequest, "некорректные данные")
				return
			}
			if _, err := db.Exec(`UPDATE communities SET is_verified=$1, updated_at=NOW() WHERE id=$2`, req.Verified, cid); err != nil {
				writeError(w, http.StatusInternalServerError, "не удалось обновить")
				return
			}
			logAdminAction(db, actorID, "community_verify", "community", cid, clientIP(r), map[string]any{"verified": req.Verified, "public_id": publicID})
			if req.Verified && creatorID != 0 {
				_ = createNotification(db, createNotificationParams{
					RecipientID:    creatorID,
					ActorID:        0,
					Type:           "community_verified",
					SourceType:     "community",
					SourceID:       cid,
					SourcePublicID: publicID,
					Title:          "Сообщество верифицировано",
					Preview:        "Ваше сообщество «" + name + "» получило отметку верификации от администрации платформы.",
				})
			}
			writeJSON(w, http.StatusOK, map[string]any{"ok": true, "is_verified": req.Verified})
			return
		}
		writeError(w, http.StatusMethodNotAllowed, "метод не поддерживается")
	}))

	mux.HandleFunc("/api/admin/export", adminAuditMiddleware(db, sessions, func(w http.ResponseWriter, r *http.Request) {
		actorID, ok := requireAdmin(w, r, db, sessions)
		if !ok {
			return
		}
		typ := strings.TrimSpace(r.URL.Query().Get("type"))
		var rows *sql.Rows
		var err error
		var header []string
		var fname string
		switch typ {
		case "users":
			fname = "users.csv"
			header = []string{"ID", "Имя", "Email", "Должность", "Город", "Админ", "Владелец", "Заблокирован", "Регистрация"}
			rows, err = db.Query(`SELECT id, COALESCE(full_name,''), email, COALESCE(position,''), COALESCE(city,''), COALESCE(is_admin,false), COALESCE(is_owner,false), (banned_at IS NOT NULL), created_at FROM users WHERE is_deleted=FALSE ORDER BY created_at DESC`)
		case "companies":
			fname = "companies.csv"
			header = []string{"ID", "Название", "ИНН", "Владелец", "Верифицирована", "Статус", "Создана"}
			rows, err = db.Query(`SELECT c.id, c.name, COALESCE(c.inn,''), COALESCE(u.full_name, u.handle, ''), COALESCE(c.is_verified,false), COALESCE(c.verification_status,'none'), c.created_at FROM companies c LEFT JOIN users u ON u.id=c.owner_user_id ORDER BY c.created_at DESC`)
		case "complaints":
			fname = "complaints.csv"
			header = []string{"ID", "От кого", "Тип цели", "Причина", "Статус", "Создана"}
			rows, err = db.Query(`SELECT c.id, COALESCE(u.full_name,''), c.target_type, COALESCE(c.reason,''), c.status, c.created_at FROM complaints c LEFT JOIN users u ON u.id=c.reporter_id ORDER BY c.created_at DESC`)
		default:
			writeError(w, http.StatusBadRequest, "Неизвестный тип экспорта")
			return
		}
		if err != nil {
			writeError(w, http.StatusInternalServerError, "Ошибка выборки")
			return
		}
		defer rows.Close()
		w.Header().Set("Content-Type", "text/csv; charset=utf-8")
		w.Header().Set("Content-Disposition", "attachment; filename=\""+fname+"\"")
		w.Write([]byte{0xEF, 0xBB, 0xBF}) // UTF-8 BOM для Excel
		cw := csv.NewWriter(w)
		cw.Write(header)
		for rows.Next() {
			cols, _ := rows.Columns()
			vals := make([]any, len(cols))
			ptrs := make([]any, len(cols))
			for i := range vals {
				ptrs[i] = &vals[i]
			}
			if rows.Scan(ptrs...) != nil {
				continue
			}
			rec := make([]string, len(cols))
			for i, v := range vals {
				switch x := v.(type) {
				case nil:
					rec[i] = ""
				case bool:
					if x {
						rec[i] = "да"
					} else {
						rec[i] = "нет"
					}
				case time.Time:
					rec[i] = x.Format("2006-01-02 15:04")
				case []byte:
					rec[i] = string(x)
				default:
					rec[i] = fmt.Sprintf("%v", x)
				}
			}
			cw.Write(rec)
		}
		cw.Flush()
		logAdminAction(db, actorID, "data.export", "export", 0, clientIP(r), map[string]any{"type": typ})
	}))

	mux.HandleFunc("/api/admin/companies", adminAuditMiddleware(db, sessions, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		if _, ok := requireAdmin(w, r, db, sessions); !ok {
			return
		}
		q := strings.TrimSpace(r.URL.Query().Get("q"))
		status := strings.TrimSpace(r.URL.Query().Get("status")) // all|pending|verified|rejected|blocked|unverified
		limit := 50
		if v := r.URL.Query().Get("limit"); v != "" {
			if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 200 {
				limit = n
			}
		}
		offset := 0
		if v := r.URL.Query().Get("offset"); v != "" {
			if n, err := strconv.Atoi(v); err == nil && n >= 0 {
				offset = n
			}
		}
		sqlQuery := `SELECT c.id, c.public_id, c.name, COALESCE(c.inn,''), COALESCE(c.logo_image,''),
		               COALESCE(u.full_name, u.handle, ''), c.owner_user_id,
		               COALESCE(c.is_verified, false), COALESCE(c.verification_status, 'none'),
		               c.created_at, c.blocked_at, COALESCE(c.blocked_reason, ''),
		               (SELECT COUNT(*) FROM company_members cm WHERE cm.company_id = c.id),
		               (SELECT COUNT(*) FROM posts p WHERE p.author_company_id = c.id AND p.is_deleted = FALSE)
		        FROM companies c
		        LEFT JOIN users u ON u.id = c.owner_user_id
		        WHERE c.deleted_at IS NULL`
		args := []any{}
		i := 1
		if q != "" {
			sqlQuery += fmt.Sprintf(" AND (LOWER(c.name) LIKE LOWER($%d) OR c.inn LIKE $%d)", i, i)
			args = append(args, "%"+q+"%")
			i++
		}
		switch status {
		case "verified":
			sqlQuery += " AND c.is_verified = TRUE AND c.blocked_at IS NULL"
		case "rejected":
			sqlQuery += " AND c.verification_status = 'rejected' AND c.blocked_at IS NULL"
		case "blocked":
			sqlQuery += " AND c.blocked_at IS NOT NULL"
		case "unverified", "pending":
			sqlQuery += " AND c.is_verified = FALSE AND c.blocked_at IS NULL"
		}
		sqlQuery += fmt.Sprintf(" ORDER BY c.created_at DESC LIMIT $%d OFFSET $%d", i, i+1)
		args = append(args, limit, offset)
		rows, err := db.Query(sqlQuery, args...)
		if err != nil {
			log.Printf("[admin/companies] %v", err)
			writeError(w, http.StatusInternalServerError, "Ошибка")
			return
		}
		defer rows.Close()
		items := []map[string]any{}
		for rows.Next() {
			var id int64
			var pub, name, inn, logo, ownerName, vstatus string
			var ownerID int64
			var isVerified bool
			var createdAt time.Time
			var blockedAt sql.NullTime
			var blockedReason string
			var members, posts int64
			if err := rows.Scan(&id, &pub, &name, &inn, &logo, &ownerName, &ownerID, &isVerified, &vstatus, &createdAt, &blockedAt, &blockedReason, &members, &posts); err != nil {
				continue
			}
			it := map[string]any{
				"id":                  id,
				"public_id":           pub,
				"name":                name,
				"inn":                 inn,
				"logo_image":          logo,
				"owner_name":          ownerName,
				"owner_user_id":       ownerID,
				"is_verified":         isVerified,
				"verification_status": vstatus,
				"created_at":          createdAt,
				"is_blocked":          blockedAt.Valid,
				"members_count":       members,
				"posts_count":         posts,
			}
			if blockedAt.Valid {
				it["blocked_at"] = blockedAt.Time
				it["blocked_reason"] = blockedReason
			}
			items = append(items, it)
		}
		writeJSON(w, http.StatusOK, map[string]any{"companies": items})
	}))

	mux.HandleFunc("/api/admin/companies/bulk", adminAuditMiddleware(db, sessions, func(w http.ResponseWriter, r *http.Request) {
		actorID, ok := requireAdmin(w, r, db, sessions)
		if !ok {
			return
		}
		if r.Method != http.MethodPost {
			writeError(w, http.StatusMethodNotAllowed, "Метод не поддерживается")
			return
		}
		var req struct {
			IDs    []string `json:"ids"`
			Action string   `json:"action"`
			Reason string   `json:"reason"`
		}
		_ = json.NewDecoder(r.Body).Decode(&req)
		if len(req.IDs) == 0 || (req.Action != "verify" && req.Action != "block") {
			writeError(w, http.StatusBadRequest, "Некорректные параметры")
			return
		}
		done := 0
		for _, pid := range req.IDs {
			var cid int64
			if db.QueryRow(`SELECT id FROM companies WHERE public_id=$1`, pid).Scan(&cid) != nil {
				continue
			}
			if req.Action == "verify" {
				if _, err := db.Exec(`UPDATE companies SET is_verified=TRUE, verification_status='verified', updated_at=NOW() WHERE id=$1`, cid); err == nil {
					logAdminAction(db, actorID, "company.verify", "company", cid, clientIP(r), map[string]any{"bulk": true})
					done++
				}
			} else {
				reason := strings.TrimSpace(req.Reason)
				if reason == "" {
					reason = "Массовая блокировка"
				}
				if _, err := db.Exec(`UPDATE companies SET blocked_at=NOW(), blocked_reason=$1, blocked_by=$2, updated_at=NOW() WHERE id=$3`, reason, actorID, cid); err == nil {
					logAdminAction(db, actorID, "company.block", "company", cid, clientIP(r), map[string]any{"bulk": true})
					done++
				}
			}
		}
		writeJSON(w, http.StatusOK, map[string]any{"done": done})
	}))

