type seedPost struct {
	PublicID   string
	Title      string
	Content    string
	Tags       []string
	CoverURL   string
	CreatedAt  time.Time
	ViewsCount int
	LikesCount int
}

func migratePublicationSeedData(db *sql.DB) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	const seedUserEmail = "seed.lastop@local"

	if _, err := tx.Exec(`
		UPDATE users SET public_id = NULL
		WHERE email = $1 AND public_id = 'usr_seed_lastop'
	`, seedUserEmail); err != nil {
		return err
	}

	var seedAuthorID int64
	if err := tx.QueryRow(`
		INSERT INTO users (public_id, first_name, last_name, full_name, email, password_hash, position, company_name, bio, avatar_url)
		VALUES ('u5eed1a5f0b', 'LASTOP', 'Digital', 'LASTOP Digital', $1, '$2a$10$H8hT4aSt3D8QdDkbx73Z9OBPFnfRTE8Yv5IadB1iKsFcfoTmya8Ie', 'Редакция LASTOP', 'LASTOP', 'Системный аккаунт для миграции публикаций', '')
		ON CONFLICT (email) DO UPDATE
		SET public_id = EXCLUDED.public_id,
		    full_name = EXCLUDED.full_name,
		    position = EXCLUDED.position,
		    company_name = EXCLUDED.company_name
		RETURNING id
	`, seedUserEmail).Scan(&seedAuthorID); err != nil {
		return err
	}

	now := time.Now().UTC()
	seeds := []seedPost{
		{
			PublicID:   "pst_seed_customs_2026",
			Title:      "ФТС обновила требования к таможенному декларированию импорта",
			Content:    "С 1 мая 2026 года вступают в силу изменения в порядке декларирования отдельных категорий товаров. Бизнесу рекомендуется заранее проверить шаблоны документов и обновить внутренние регламенты.",
			Tags:       []string{"таможня", "вэд", "регуляторика"},
			CreatedAt:  now.Add(-18 * time.Hour),
			ViewsCount: 1820,
			LikesCount: 47,
		},
		{
			PublicID:   "pst_seed_routes_2026",
			Title:      "Рынок фиксирует рост контейнерных перевозок на 18% в Q2 2026",
			Content:    "Участники отрасли связывают рост с развитием альтернативных международных маршрутов и повышением прозрачности цифрового трекинга грузов.",
			Tags:       []string{"логистика", "контейнеры", "аналитика"},
			CreatedAt:  now.Add(-48 * time.Hour),
			ViewsCount: 2400,
			LikesCount: 52,
		},
		{
			PublicID:   "pst_seed_tms_ai",
			Title:      "LASTOP Digital запустил модуль аналитики TMS с ИИ‑прогнозированием",
			Content:    "Новый модуль помогает предсказывать отклонения SLA и автоматически сигнализирует о рисках на отдельных участках цепочки поставок.",
			Tags:       []string{"технологии", "tms", "ai"},
			CreatedAt:  now.Add(-72 * time.Hour),
			ViewsCount: 940,
			LikesCount: 34,
		},
	}

	for _, item := range seeds {
		var pgTags pgtype.FlatArray[string] = item.Tags

		if _, err := tx.Exec(`
			INSERT INTO posts (public_id, author_id, type, title, content, tags, cover_url, privacy_level, views_count, likes_count, created_at, updated_at)
			VALUES ($1, $2, 'news', $3, $4, $5, NULLIF($6, ''), 'public', $7, $8, $9, NOW())
			ON CONFLICT (public_id) DO NOTHING
		`, item.PublicID, seedAuthorID, item.Title, item.Content, pgTags, item.CoverURL, item.ViewsCount, item.LikesCount, item.CreatedAt); err != nil {
			return err
		}
	}

	return tx.Commit()
}

var (
	errValidation         = errors.New("validation error")
	errEmailTaken         = errors.New("email taken")
	errInvalidCredentials = errors.New("invalid credentials")
	errConflict           = errors.New("conflict")
	errNotFound           = errors.New("not found")
	errForbidden          = errors.New("forbidden")
	errHandleTaken        = errors.New("handle taken")
	errAlreadyMember      = errors.New("already member")
	errRequestPending     = errors.New("request pending")

	handleRe        = regexp.MustCompile(`^[a-z0-9][a-z0-9_]{2,23}$`)
	mentionRe       = regexp.MustCompile(`(?i)@([a-z0-9_]{3,24})`)
	reservedHandles = map[string]struct{}{
		"admin": {}, "root": {}, "support": {}, "system": {}, "anonymous": {},
		"lastop": {}, "help": {}, "api": {}, "bot": {}, "null": {}, "undefined": {},
		"deleted": {}, "me": {}, "settings": {}, "profile": {}, "chat": {},
		"news": {}, "forum": {}, "jobs": {}, "events": {}, "communities": {},
		"companies": {}, "login": {}, "register": {}, "logout": {},
		"new": {}, "edit": {}, "delete": {},
	}
)

func createUser(db *sql.DB, req registerRequest, clientIPAddr string) (user, error) {
	if strings.TrimSpace(req.FirstName) == "" {
		return user{}, fmt.Errorf("%w: имя обязательно", errValidation)
	}
	if strings.TrimSpace(req.LastName) == "" {
		return user{}, fmt.Errorf("%w: фамилия обязательна", errValidation)
	}
	email := strings.ToLower(strings.TrimSpace(req.Email))
	if !isValidEmail(email) {
		return user{}, fmt.Errorf("%w: email некорректен", errValidation)
	}
	if len(req.Password) < 8 {
		return user{}, fmt.Errorf("%w: пароль должен быть не короче 8 символов", errValidation)
	}
	if !req.Terms {
		return user{}, fmt.Errorf("%w: необходимо принять условия", errValidation)
	}

	hash, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
	if err != nil {
		return user{}, fmt.Errorf("hash password: %w", err)
	}

	fullName := strings.TrimSpace(req.FullName)
	if fullName == "" {
		fullName = strings.TrimSpace(req.FirstName + " " + req.LastName)
	}

	for attempts := 0; attempts < 5; attempts++ {
		publicID, genErr := newPublicUserID()
		if genErr != nil {
			return user{}, fmt.Errorf("generate public_id: %w", genErr)
		}

		var created user
		err = db.QueryRow(`
			INSERT INTO users(public_id, first_name, last_name, full_name, email, password_hash, terms_accepted_at, terms_accepted_ip)
			VALUES ($1, $2, $3, $4, $5, $6, NOW(), NULLIF($7, ''))
			RETURNING id, public_id, first_name, last_name, full_name, email,
				COALESCE(position, ''), COALESCE(company_name, ''), COALESCE(bio, ''),
				COALESCE(phone, ''), COALESCE(location, ''), COALESCE(city, ''), COALESCE(avatar_url, ''), COALESCE(handle, '')
		`, publicID, strings.TrimSpace(req.FirstName), strings.TrimSpace(req.LastName), fullName, email, string(hash), clientIPAddr).
			Scan(&created.ID, &created.PublicID, &created.FirstName, &created.LastName, &created.FullName, &created.Email, &created.Position, &created.CompanyName, &created.Bio, &created.Phone, &created.Location, &created.City, &created.AvatarURL, &created.Handle)
		if err == nil {
			return created, nil
		}

		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) {
			if pgErr.Code == "23505" && pgErr.ConstraintName == "users_email_key" {
				return user{}, errEmailTaken
			}
			if pgErr.Code == "23505" {
				continue
			}
		}

		return user{}, err
	}

	return user{}, fmt.Errorf("failed to allocate public_id")
}

func loginUser(db *sql.DB, req loginRequest) (user, error) {
	email := strings.ToLower(strings.TrimSpace(req.Email))
	if !isValidEmail(email) {
		return user{}, fmt.Errorf("%w: email некорректен", errValidation)
	}
	if strings.TrimSpace(req.Password) == "" {
		return user{}, fmt.Errorf("%w: пароль обязателен", errValidation)
	}

	var u user
	var passwordHash string
	var bannedAt sql.NullTime
	var bannedReason string
	err := db.QueryRow(`
		SELECT id, public_id, first_name, last_name, full_name, email,
			COALESCE(position, ''), COALESCE(company_name, ''), COALESCE(bio, ''),
			COALESCE(phone, ''), COALESCE(location, ''), COALESCE(city, ''), COALESCE(avatar_url, ''), COALESCE(handle, ''),
			password_hash, banned_at, COALESCE(banned_reason, '')
		FROM users
		WHERE email = $1 AND is_deleted = FALSE
	`, email).Scan(&u.ID, &u.PublicID, &u.FirstName, &u.LastName, &u.FullName, &u.Email, &u.Position, &u.CompanyName, &u.Bio, &u.Phone, &u.Location, &u.City, &u.AvatarURL, &u.Handle, &passwordHash, &bannedAt, &bannedReason)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			// Phase 4 (19.05) SEC: dummy bcrypt-compare для уравнивания
			// времени отклика. Без этого атакующий по разнице в latency
			// (несколько мс vs ~100мс) детектирует существование email
			// в базе (user enumeration через timing attack).
			//
			// Hash сгенерирован один раз через bcrypt("dummy-password", DefaultCost).
			// Сам пароль не важен — главное чтобы Compare выполнял полный
			// объём работы (cost=10 ≈ 100мс), не отличимый от реального.
			_ = bcrypt.CompareHashAndPassword(
				[]byte("$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy"),
				[]byte(req.Password),
			)
			return user{}, errInvalidCredentials
		}
		return user{}, err
	}

	if err := bcrypt.CompareHashAndPassword([]byte(passwordHash), []byte(req.Password)); err != nil {
		return user{}, errInvalidCredentials
	}
	if bannedAt.Valid {
		if strings.TrimSpace(bannedReason) == "" {
			bannedReason = "Аккаунт заблокирован"
		}
		return user{}, fmt.Errorf("%w: %s", errForbidden, bannedReason)
	}

	return u, nil
}

func getPublicUserProfile(db *sql.DB, publicID string, viewerID int64) (publicUserProfile, error) {
	var profile publicUserProfile
	var ownerID int64
	err := db.QueryRow(`
		SELECT id, public_id, first_name, last_name, full_name, email, COALESCE(handle, ''),
			COALESCE(avatar_url, ''), COALESCE(cover_url, ''), COALESCE(position, ''), COALESCE(company_name, ''),
			COALESCE(bio, ''), COALESCE(phone, ''), COALESCE(location, ''), COALESCE(city, '')
		FROM users
		WHERE public_id = $1 AND is_deleted = FALSE
	`, publicID).Scan(
		&ownerID,
		&profile.PublicID,
		&profile.FirstName,
		&profile.LastName,
		&profile.FullName,
		&profile.Email,
		&profile.Handle,
		&profile.AvatarURL,
		&profile.CoverURL,
		&profile.Position,
		&profile.CompanyName,
		&profile.Bio,
		&profile.Phone,
		&profile.Location,
		&profile.City,
	)
	profile.ID = ownerID
	if err != nil {
		return publicUserProfile{}, err
	}
	isSelf := viewerID > 0 && viewerID == ownerID
	profile.IsSelf = isSelf
	settings, err := loadUserSettings(db, ownerID)
	if err != nil {
		settings = userSettings{
			PrivacyProfilePrivate: false,
			PrivacyShowEmail:      false,
			PrivacyShowPhone:      false,
			PrivacyShowOnline:     true,
			PrivacyShowLastSeen:   false,
			PrivacyWhoCanMessage:  "all",
		}
	}
	isFriend := false
	if !isSelf && viewerID > 0 {
		var s string
		_ = db.QueryRow(`SELECT status FROM friend_requests WHERE ((requester_id=$1 AND addressee_id=$2) OR (requester_id=$2 AND addressee_id=$1)) AND status='accepted' LIMIT 1`, viewerID, ownerID).Scan(&s)
		isFriend = s == "accepted"
	}
	profile.IsPrivate = settings.PrivacyProfilePrivate && !isSelf && !isFriend
	if profile.IsPrivate {
		profile.FirstName = ""
		profile.LastName = ""
		profile.Position = ""
		profile.CompanyName = ""
		profile.Bio = ""
		profile.Phone = ""
		profile.Email = ""
		profile.Location = ""
		profile.City = ""
		profile.CanMessage = false
		return profile, nil
	}
	if !isSelf && !settings.PrivacyShowEmail {
		profile.Email = ""
	}
	if !isSelf && !settings.PrivacyShowPhone {
		profile.Phone = ""
	}
	if isSelf || settings.PrivacyShowOnline {
		profile.IsOnline = hasActiveSession(db, ownerID)
	}
	if isSelf || settings.PrivacyShowLastSeen {
		var seen sql.NullTime
		if err := db.QueryRow(`SELECT MAX(last_seen_at) FROM sessions WHERE user_id=$1`, ownerID).Scan(&seen); err == nil && seen.Valid {
			formatted := seen.Time.UTC().Format(time.RFC3339)
			profile.LastSeenAt = &formatted
		}
	}
	profile.CanMessage = canViewerMessageOwner(db, viewerID, ownerID, settings.PrivacyWhoCanMessage)
	profile.FriendStatus = computeFriendStatus(db, viewerID, ownerID)
	return profile, nil
}

// computeFriendStatus возвращает статус отношения viewerID к ownerID:
//
//	"self"     — это сам юзер
//	"friends"  — заявка accepted
//	"outgoing" — viewer отправил заявку (pending)
//	"incoming" — owner отправил заявку viewer'у (pending)
//	"none"     — никаких отношений (или были rejected/canceled/unfriended)
//
// Если viewerID == 0 (не авторизован) — возвращает "none".
func computeFriendStatus(db *sql.DB, viewerID, ownerID int64) string {
	if viewerID == 0 {
		return "none"
	}
	if viewerID == ownerID {
		return "self"
	}
	var requesterID, addresseeID int64
	var status string
	err := db.QueryRow(`
		SELECT requester_id, addressee_id, status
		FROM friend_requests
		WHERE (requester_id = $1 AND addressee_id = $2)
		   OR (requester_id = $2 AND addressee_id = $1)
		ORDER BY CASE status
			WHEN 'accepted' THEN 1
			WHEN 'pending' THEN 2
			ELSE 3
		END, updated_at DESC
		LIMIT 1
	`, viewerID, ownerID).Scan(&requesterID, &addresseeID, &status)
	if err != nil {
		return "none" // нет записи или ошибка → none
	}
	switch status {
	case "accepted":
		return "friends"
	case "pending":
		if requesterID == viewerID {
			return "outgoing"
		}
		return "incoming"
	default:
		// rejected, canceled, unfriended → можно отправить новую
		return "none"
	}
}

func canViewerMessageOwner(db *sql.DB, viewerID, ownerID int64, whoCanMessage string) bool {
	if viewerID == 0 || viewerID == ownerID {
		return false
	}
	switch strings.TrimSpace(strings.ToLower(whoCanMessage)) {
	case "nobody":
		return false
	case "contacts":
		var hasContact bool
		err := db.QueryRow(`
			SELECT EXISTS(
				SELECT 1
				FROM chat_conversations cc
				JOIN chat_participants p1 ON p1.conversation_id = cc.id AND p1.user_id = $1
				JOIN chat_participants p2 ON p2.conversation_id = cc.id AND p2.user_id = $2
				WHERE cc.type = 'direct'
			)
		`, viewerID, ownerID).Scan(&hasContact)
		return err == nil && hasContact
	default:
		return true
	}
}

func hasActiveSession(db *sql.DB, userID int64) bool {
	// «Онлайн» = у юзера есть сессия, в которой last_seen_at обновлялся
	// за последние 5 минут. last_seen_at обновляется при каждом
	// авторизованном запросе (UPDATE sessions SET last_seen_at = NOW()),
	// поэтому критерий точный: пока юзер активно ходит по платформе —
	// он «онлайн», когда уходит — через 5 минут гаснет.
	// Раньше критерием было expires_at > NOW(), но сессии живут 30 дней,
	// и любой юзер заходивший за месяц считался «онлайн» — это неверно.
	var isOnline bool
	err := db.QueryRow(`SELECT EXISTS(SELECT 1 FROM sessions WHERE user_id=$1 AND last_seen_at > NOW() - INTERVAL '5 minutes')`, userID).Scan(&isOnline)
	return err == nil && isOnline
}

func getUserByID(db *sql.DB, userID int64) (user, error) {
	var u user
	var verifiedAt sql.NullTime
	err := db.QueryRow(`
		SELECT id, public_id, first_name, last_name, full_name, email,
			COALESCE(position, ''), COALESCE(company_name, ''), COALESCE(bio, ''),
			COALESCE(phone, ''), COALESCE(location, ''), COALESCE(city, ''), COALESCE(avatar_url, ''), COALESCE(cover_url, ''), COALESCE(handle, ''), COALESCE(is_admin, FALSE), COALESCE(is_owner, FALSE),
			COALESCE(analytics_visible_in_viewers, TRUE), email_verified_at
		FROM users
		WHERE id = $1 AND is_deleted = FALSE
	`, userID).Scan(&u.ID, &u.PublicID, &u.FirstName, &u.LastName, &u.FullName, &u.Email, &u.Position, &u.CompanyName, &u.Bio, &u.Phone, &u.Location, &u.City, &u.AvatarURL, &u.CoverURL, &u.Handle, &u.IsAdmin, &u.IsOwner, &u.AnalyticsVisibleInViewers, &verifiedAt)
	if err != nil {
		return user{}, err
	}
	u.EmailVerified = verifiedAt.Valid

	return u, nil
}

// requireOwner проверяет что у юзера is_owner = true.
func requireOwner(w http.ResponseWriter, r *http.Request, db *sql.DB, sessions *sessionStore) (int64, bool) {
	token, _ := tokenFromRequest(r)
	if token == "" {
		writeError(w, http.StatusUnauthorized, "Требуется авторизация")
		return 0, false
	}
	userID, ok := sessions.getUserID(token)
	if !ok {
		writeError(w, http.StatusUnauthorized, "Сессия недействительна")
		return 0, false
	}
	var isOwner bool
	var bannedAt sql.NullTime
	if err := db.QueryRow(`SELECT COALESCE(is_owner, FALSE), banned_at FROM users WHERE id = $1`, userID).Scan(&isOwner, &bannedAt); err != nil {
		writeError(w, http.StatusInternalServerError, "Ошибка проверки прав")
		return 0, false
	}
	if bannedAt.Valid {
		writeError(w, http.StatusForbidden, "Доступ запрещён")
		return 0, false
	}
	if !isOwner {
		writeError(w, http.StatusForbidden, "Требуются права владельца")
		return 0, false
	}
	return userID, true
}

// requireAdmin проверяет что у юзера is_admin = true.
// Возвращает userID и true если ок. Если нет — пишет ошибку в ResponseWriter и возвращает false.
func requireAdmin(w http.ResponseWriter, r *http.Request, db *sql.DB, sessions *sessionStore) (int64, bool) {
	token, _ := tokenFromRequest(r)
	if token == "" {
		writeError(w, http.StatusUnauthorized, "Требуется авторизация")
		return 0, false
	}
	userID, ok := sessions.getUserID(token)
	if !ok {
		writeError(w, http.StatusUnauthorized, "Сессия недействительна")
		return 0, false
	}
	var isAdmin bool
	var bannedAt sql.NullTime
	if err := db.QueryRow(`SELECT COALESCE(is_admin, FALSE), banned_at FROM users WHERE id = $1`, userID).Scan(&isAdmin, &bannedAt); err != nil {
		writeError(w, http.StatusInternalServerError, "Ошибка проверки прав")
		return 0, false
	}
	if bannedAt.Valid {
		writeError(w, http.StatusForbidden, "Аккаунт заблокирован")
		return 0, false
	}
	if !isAdmin {
		writeError(w, http.StatusForbidden, "Доступ только для администраторов")
		return 0, false
	}
	return userID, true
}

func isUserAdmin(db *sql.DB, userID int64) (bool, error) {
	var isAdmin bool
	if err := db.QueryRow(`SELECT COALESCE(is_admin, FALSE) FROM users WHERE id = $1`, userID).Scan(&isAdmin); err != nil {
		return false, err
	}
	return isAdmin, nil
}

// isUserBanned проверяет, заблокирован ли юзер (banned_at IS NOT NULL).
// ── Система санкций ──
const (
	escalateWarnToMute   = 3
	escalateMuteToBan    = 2
	escalationWindowDays = 90
	autoMuteDays         = 7
	autoBanDays          = 30
)

var muteScopeAll = []string{"post", "comment", "chat", "forum", "event", "job"}

// isUserBanned: бан с lazy-автоснятием по banned_until.
func isUserBanned(db *sql.DB, userID int64) (bool, string, error) {
	var bannedAt, bannedUntil sql.NullTime
	var reason sql.NullString
	if err := db.QueryRow(`SELECT banned_at, banned_until, banned_reason FROM users WHERE id = $1`, userID).Scan(&bannedAt, &bannedUntil, &reason); err != nil {
		return false, "", err
	}
	if !bannedAt.Valid {
		return false, "", nil
	}
	if bannedUntil.Valid && bannedUntil.Time.Before(time.Now()) {
		_, _ = db.Exec(`UPDATE users SET banned_at=NULL, banned_until=NULL, banned_reason=NULL, banned_by=NULL WHERE id=$1`, userID)
		_, _ = db.Exec(`UPDATE user_sanctions SET lifted_at=NOW() WHERE user_id=$1 AND type='ban' AND lifted_at IS NULL`, userID)
		return false, "", nil
	}
	return true, reason.String, nil
}

// isUserMuted: mute с lazy-снятием и проверкой scope.
func isUserMuted(db *sql.DB, userID int64, scope string) (bool, time.Time, string) {
	var mutedUntil sql.NullTime
	var scopesJSON []byte
	var reason string
	if err := db.QueryRow(`SELECT muted_until, array_to_json(mute_scopes), mute_reason FROM users WHERE id=$1`, userID).Scan(&mutedUntil, &scopesJSON, &reason); err != nil {
		return false, time.Time{}, ""
	}
	if !mutedUntil.Valid {
		return false, time.Time{}, ""
	}
	if mutedUntil.Time.Before(time.Now()) {
		_, _ = db.Exec(`UPDATE users SET muted_until=NULL, mute_scopes='{}', mute_reason='', muted_by=NULL WHERE id=$1`, userID)
		_, _ = db.Exec(`UPDATE user_sanctions SET lifted_at=NOW() WHERE user_id=$1 AND type='mute' AND lifted_at IS NULL`, userID)
		return false, time.Time{}, ""
	}
	var scopes []string
	_ = json.Unmarshal(scopesJSON, &scopes)
	for _, s := range scopes {
		if s == scope {
			return true, mutedUntil.Time, reason
		}
	}
	return false, time.Time{}, ""
}

// sanctionNotify — стилизованное уведомление о санкции (категория «Модерация»).
func sanctionNotify(db *sql.DB, userID int64, title, body string) {
	_, _ = db.Exec(`DELETE FROM notifications WHERE recipient_id=$1 AND type='moderation_sanction' AND actor_id IS NULL`, userID)
	_ = createNotification(db, createNotificationParams{
		RecipientID: userID,
		ActorID:     0,
		Type:        "moderation_sanction",
		Title:       title,
		Preview:     body,
	})
}

// applySanction накладывает санкцию: история + состояние users + уведомление + разрыв сессий (ban) + автоэскалация.
func applySanction(db *sql.DB, userID int64, sType string, scopes []string, reason string, durationDays int, createdBy int64, isAuto bool) error {
	var expires any
	if sType != "warn" && durationDays > 0 {
		expires = time.Now().AddDate(0, 0, durationDays)
	}
	var createdByArg any
	if createdBy != 0 {
		createdByArg = createdBy
	}
	if _, err := db.Exec(`
		INSERT INTO user_sanctions (user_id, type, scopes, reason, duration_days, created_by, is_auto, expires_at)
		VALUES ($1,$2,$3::text[],$4,$5,$6,$7,$8)`,
		userID, sType, pgtype.FlatArray[string](scopes), reason, durationDays, createdByArg, isAuto, expires); err != nil {
		return err
	}
	switch sType {
	case "warn":
		sanctionNotify(db, userID, "Предупреждение от администрации", reason)
	case "mute":
		until := time.Now().AddDate(0, 0, durationDays)
		if _, err := db.Exec(`UPDATE users SET muted_until=$1, mute_scopes=$2::text[], mute_reason=$3, muted_by=NULLIF($4,0) WHERE id=$5`, until, pgtype.FlatArray[string](scopes), reason, createdBy, userID); err != nil {
			return err
		}
		sanctionNotify(db, userID, "Ограничение публикации", "Вы временно ограничены в действиях до "+until.Format("02.01.2006")+". Причина: "+reason)
	case "ban":
		var until any
		msg := "Ваш аккаунт заблокирован бессрочно. Причина: " + reason
		if durationDays > 0 {
			u := time.Now().AddDate(0, 0, durationDays)
			until = u
			msg = "Ваш аккаунт заблокирован до " + u.Format("02.01.2006") + ". Причина: " + reason
		}
		if _, err := db.Exec(`UPDATE users SET banned_at=NOW(), banned_until=$1, banned_reason=$2, banned_by=$3 WHERE id=$4`, until, reason, createdByArg, userID); err != nil {
			return err
		}
		sanctionNotify(db, userID, "Аккаунт заблокирован", msg)
		sessions.invalidateUser(userID)
	}
	if !isAuto {
		checkAutoEscalation(db, userID)
	}
	return nil
}

// checkAutoEscalation: при превышении порогов накладывает следующую ступень.
func checkAutoEscalation(db *sql.DB, userID int64) {
	since := time.Now().AddDate(0, 0, -escalationWindowDays)
	var warnCount, muteCount int
	_ = db.QueryRow(`SELECT COUNT(*) FROM user_sanctions WHERE user_id=$1 AND type='warn' AND created_at>=$2`, userID, since).Scan(&warnCount)
	_ = db.QueryRow(`SELECT COUNT(*) FROM user_sanctions WHERE user_id=$1 AND type='mute' AND created_at>=$2`, userID, since).Scan(&muteCount)
	if banned, _, _ := isUserBanned(db, userID); banned {
		return
	}
	if muteCount >= escalateMuteToBan {
		_ = applySanction(db, userID, "ban", nil, "Автоматическая блокировка: повторные нарушения", autoBanDays, 0, true)
		return
	}
	if warnCount >= escalateWarnToMute {
		if muted, _, _ := isUserMuted(db, userID, "post"); !muted {
			_ = applySanction(db, userID, "mute", muteScopeAll, "Автоматическое ограничение: повторные предупреждения", autoMuteDays, 0, true)
		}
	}
}

// liftSanction досрочно снимает активную санкцию (mute|ban).
func liftSanction(db *sql.DB, userID int64, sType string, liftedBy int64) error {
	switch sType {
	case "mute":
		if _, err := db.Exec(`UPDATE users SET muted_until=NULL, mute_scopes='{}', mute_reason='', muted_by=NULL WHERE id=$1`, userID); err != nil {
			return err
		}
	case "ban":
		if _, err := db.Exec(`UPDATE users SET banned_at=NULL, banned_until=NULL, banned_reason=NULL, banned_by=NULL WHERE id=$1`, userID); err != nil {
			return err
		}
	}
	_, _ = db.Exec(`UPDATE user_sanctions SET lifted_at=NOW(), lifted_by=$1 WHERE user_id=$2 AND type=$3 AND lifted_at IS NULL`, liftedBy, userID, sType)
	sanctionNotify(db, userID, "Ограничения сняты", "Администрация досрочно сняла наложенные ограничения.")
	return nil
}

// checkMute возвращает errValidation с понятным текстом, если юзер заглушён для данной области.
func checkMute(db *sql.DB, userID int64, scope string) error {
	muted, until, reason := isUserMuted(db, userID, scope)
	if !muted {
		return nil
	}
	msg := "Вы временно ограничены в этом действии до " + until.Format("02.01.2006")
	if reason != "" {
		msg += ". Причина: " + reason
	}
	return fmt.Errorf("%w: %s", errValidation, msg)
}

// SEC-COOKIE-AUTH (18.05): двойная-cookie аутентификация с CSRF-защитой.
//
// При login/register сервер ставит:
//   lastop_session  — HttpOnly + Secure + SameSite=Lax (JS не видит)
//   lastop_csrf     — НЕ HttpOnly + Secure + SameSite=Lax (JS читает)
//
// На write-запросах (POST/PUT/DELETE/PATCH) фронт обязан положить
// значение csrf-cookie в header X-CSRF-Token. Сервер сверяет хедер
// с csrf_token из таблицы sessions для текущей session-cookie.
//
// Гибридный режим: проверка CSRF запускается ТОЛЬКО для запросов
// которые авторизовались через cookie (не через Authorization: Bearer).
// Bearer сам по себе защищает от CSRF, поэтому не требует доп. проверки.

const (
	authCookieName = "lastop_session"
	csrfCookieName = "lastop_csrf"
	csrfHeaderName = "X-CSRF-Token"
)

func setAuthCookies(w http.ResponseWriter, sessionToken, csrfToken string, maxAge time.Duration) {
	// SEC: session cookie — SameSite=Lax (было Strict до 23.05).
	// Strict ломал переход по прямым ссылкам (деталки из чата/мессенджера): cookie
	// не отправлялась при top-level навигации с внешнего origin → serveDetailWithOG
	// рендерил гостевую пустую деталку (баг B-LINK-AUTH, Mozilla/Yandex строже).
	// Lax безопасен: cookie не уходит на cross-site POST/iframe; CSRF закрыт отдельным
	// токеном в X-CSRF-Token header (csrf cookie ниже). Lax — рекомендованный дефолт.
	http.SetCookie(w, &http.Cookie{Name: authCookieName, Value: sessionToken, Path: "/", HttpOnly: true, Secure: true, SameSite: http.SameSiteLaxMode, MaxAge: int(maxAge.Seconds())})
	// CSRF cookie оставляем Lax: она НЕ HttpOnly, JS читает её сам и кладёт
	// в X-CSRF-Token header — поведение SameSite не критично.
	http.SetCookie(w, &http.Cookie{Name: csrfCookieName, Value: csrfToken, Path: "/", HttpOnly: false, Secure: true, SameSite: http.SameSiteLaxMode, MaxAge: int(maxAge.Seconds())})
}

func clearAuthCookies(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{Name: authCookieName, Value: "", Path: "/", HttpOnly: true, Secure: true, SameSite: http.SameSiteLaxMode, MaxAge: -1})
	http.SetCookie(w, &http.Cookie{Name: csrfCookieName, Value: "", Path: "/", HttpOnly: false, Secure: true, SameSite: http.SameSiteLaxMode, MaxAge: -1})
}

// tokenFromRequest — токен ТОЛЬКО из cookie (Phase 3 19.05).
// Bearer fallback убран — авторизация полностью через HttpOnly cookies.
// Сохраняем сигнатуру с fromCookie для совместимости (всегда true).
func tokenFromRequest(r *http.Request) (token string, fromCookie bool) {
	if c, err := r.Cookie(authCookieName); err == nil && c.Value != "" {
		return c.Value, true
	}
	return "", false
}

func isWriteMethod(m string) bool {
	return m == http.MethodPost || m == http.MethodPut || m == http.MethodDelete || m == http.MethodPatch
}

func checkCSRF(r *http.Request, expected string) bool {
	if expected == "" {
		return false
	}
	provided := r.Header.Get(csrfHeaderName)
	if provided == "" {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(provided), []byte(expected)) == 1
}

func authenticatedUserID(w http.ResponseWriter, r *http.Request, sessions *sessionStore) (int64, bool) {
	token, fromCookie := tokenFromRequest(r)
	if token == "" {
		writeError(w, http.StatusUnauthorized, "Требуется авторизация")
		return 0, false
	}
	if fromCookie && isWriteMethod(r.Method) {
		userID, csrf, ok := sessions.getUserIDWithCSRF(token)
		if !ok {
			writeError(w, http.StatusUnauthorized, "Сессия не найдена")
			return 0, false
		}
		if !checkCSRF(r, csrf) {
			writeError(w, http.StatusForbidden, "Недействительный CSRF-токен")
			return 0, false
		}
		if banned, _, err := isUserBanned(sessions.db, userID); err == nil && banned {
			writeError(w, http.StatusForbidden, "Аккаунт заблокирован")
			return 0, false
		}
		return userID, true
	}
	userID, ok := sessions.getUserID(token)
	if !ok {
		writeError(w, http.StatusUnauthorized, "Сессия не найдена")
		return 0, false
	}
	if banned, _, err := isUserBanned(sessions.db, userID); err == nil && banned {
		writeError(w, http.StatusForbidden, "Аккаунт заблокирован")
		return 0, false
	}
	return userID, true
}

func optionalAuthenticatedUserID(r *http.Request, sessions *sessionStore) (int64, bool) {
	token, _ := tokenFromRequest(r)
	if token == "" {
		return 0, false
	}
	userID, ok := sessions.getUserID(token)
	if !ok {
		return 0, false
	}
	return userID, true
}

// createNotification создаёт уведомление для recipient'а.
// Идемпотентно через unique-индекс: одно событие одного типа от одного актора
// по одному источнику = одна запись.
//
// Не пишет уведомление если:
//   - recipient == actor (юзер сам себе);
//   - recipient'а не существует;
//   - у recipient'а соответствующий notif-тогл выключен (для известных типов).
//
// Не возвращает ошибку если уведомление "не нужно создавать" — это нормальный путь.
func createNotification(db *sql.DB, p createNotificationParams) error {
	if p.RecipientID == 0 || strings.TrimSpace(p.Type) == "" || strings.TrimSpace(p.Title) == "" {
		return fmt.Errorf("createNotification: invalid params")
	}
	if p.RecipientID == p.ActorID && p.ActorID != 0 {
		return nil
	}

	var recipientExists bool
	if err := db.QueryRow(`SELECT EXISTS(SELECT 1 FROM users WHERE id = $1 AND is_deleted = FALSE)`, p.RecipientID).Scan(&recipientExists); err != nil || !recipientExists {
		return nil
	}

	if !shouldCreateNotificationForType(db, p.RecipientID, p.Type) {
		return nil
	}

	title := strings.TrimSpace(p.Title)
	if utf8.RuneCountInString(title) > 500 {
		runes := []rune(title)
		title = string(runes[:500])
	}
	preview := strings.TrimSpace(p.Preview)
	if utf8.RuneCountInString(preview) > 1000 {
		runes := []rune(preview)
		preview = string(runes[:1000])
	}

	var actorIDArg any
	if p.ActorID != 0 {
		actorIDArg = p.ActorID
	}

	_, err := db.Exec(`
		INSERT INTO notifications (recipient_id, actor_id, type, source_type, source_id, source_public_id, anchor, title, preview)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
		ON CONFLICT DO NOTHING`,
		p.RecipientID, actorIDArg, p.Type, p.SourceType, p.SourceID, p.SourcePublicID, p.Anchor, title, preview)
	if err == nil {
		// Real-time push: уведомляем подключённого клиента, чтобы бейдж обновился без polling.
		wsHub.Send(p.RecipientID, "notif:new", map[string]any{
			"type":             p.Type,
			"source_type":      p.SourceType,
			"source_id":        p.SourceID,
			"source_public_id": p.SourcePublicID,
			"anchor":           p.Anchor,
			"title":            title,
			"preview":          preview,
		})
		// Web-push: асинхронно шлём системное уведомление всем устройствам юзера.
		// Tag = type:source_id — одинаковый tag заменяет предыдущую нотификацию,
		// чтобы не накапливались дубли при апдейтах.
		// Для chat_message title переопределяем на чистое имя отправителя —
		// в push контекст «это чат» виден из URL домена и иконки, дублировать
		// «написал вам» избыточно. Для остальных типов оставляем title как есть.
		pushTitle := title
		pushBody := preview
		if p.Type == "chat_message" {
			// title для chat_message приходит как "<actorName> написал вам" —
			// срезаем суффикс если он есть, оставляем только имя.
			pushTitle = strings.TrimSuffix(title, " написал вам")
		}
		go pushnotify.SendToUser(context.Background(), db, p.RecipientID, pushnotify.Payload{
			Title:     pushTitle,
			Body:      pushBody,
			Tag:       fmt.Sprintf("%s-%d", p.Type, p.SourceID),
			URL:       pushnotify.URLForNotification(p.Type, p.SourceType, p.SourcePublicID),
			NotifType: p.Type,
		})
	}
	return err
}

// shouldCreateNotificationForType решает, нужно ли создавать уведомление,
// глядя на тогл соответствующей категории в settings юзера.
// Если тип неизвестен или тогл не определён — пропускает (создаёт).
func shouldCreateNotificationForType(db *sql.DB, userID int64, notifType string) bool {
	var col string
	switch notifType {
	case "post_like", "comment_like":
		col = "notif_reactions"
	case "post_comment", "comment_reply", "forum_reply", "forum_quote", "forum_like":
		col = "notif_reactions"
	case "job_application":
		col = "notif_chat_messages"
	case "catalog_order":
		col = "notif_chat_messages"
	case "mention":
		col = "notif_mentions"
	case "friend_request", "friend_accepted":
		col = "notif_friend_requests"
	case "chat_message":
		col = "notif_chat_messages"
	default:
		return true
	}

	var enabled bool
	err := db.QueryRow(fmt.Sprintf(`SELECT %s FROM users WHERE id = $1 AND is_deleted = FALSE`, col), userID).Scan(&enabled)
	if err != nil {
		return true
	}
	return enabled
}

// getUserDisplayName возвращает отображаемое имя юзера (full_name, или handle если имени нет).
// Используется в текстах уведомлений.
func getUserDisplayName(db *sql.DB, userID int64) string {
	if userID == 0 {
		return "Кто-то"
	}
	var fullName, handle string
	err := db.QueryRow(`SELECT COALESCE(full_name, ''), COALESCE(handle, '') FROM users WHERE id = $1`, userID).Scan(&fullName, &handle)
	if err != nil {
		return "Кто-то"
	}
	fullName = strings.TrimSpace(fullName)
	if fullName != "" {
		return fullName
	}
	if handle != "" {
		return "@" + handle
	}
	return "Кто-то"
}

func canManageProject(db *sql.DB, projectID, userID int64) bool {
	if userID == 0 {
		return false
	}
	var role string
	err := db.QueryRow(`
		SELECT role FROM project_members
		WHERE project_id = $1 AND user_id = $2
	`, projectID, userID).Scan(&role)
	if err != nil {
		return false
	}
	return role == "owner" || role == "admin"
}

func isProjectMember(db *sql.DB, projectID, userID int64) bool {
	if userID == 0 {
		return false
	}
	var exists bool
	err := db.QueryRow(`
		SELECT EXISTS(SELECT 1 FROM project_members WHERE project_id = $1 AND user_id = $2)
	`, projectID, userID).Scan(&exists)
	return err == nil && exists
}

func getProjectIDByPublicID(db *sql.DB, publicID string) (int64, error) {
	var id int64
	err := db.QueryRow(`SELECT id FROM projects WHERE public_id = $1 AND is_deleted = FALSE`, publicID).Scan(&id)
	return id, err
}

